import { getDb } from './db'
import {
  DEFAULT_SETTINGS,
  type LegacySettingsFields,
  type SettingsRecord,
} from './settings-types'
import {
  buildDefaultProfile,
  ensureAtLeastOneProfile,
  getProfile,
  listProfiles,
  saveProfile,
  DEFAULT_PROFILE_NAME,
  type ProfileRecord,
} from './profiles'
import type { DrillConfig } from '../engine/types'

export { DEFAULT_SETTINGS, type SettingsRecord } from './settings-types'

export async function loadSettings(): Promise<SettingsRecord> {
  const db = getDb()
  if (!db) return DEFAULT_SETTINGS
  try {
    const row = await db.settings.get('singleton')
    if (!row) return DEFAULT_SETTINGS
    // Strip any legacy drill fields when returning to callers.
    const { id, commitKeyCode, commitKeyLabel, inputSource, activeProfileId } = {
      ...DEFAULT_SETTINGS,
      ...row,
    }
    return { id, commitKeyCode, commitKeyLabel, inputSource, activeProfileId }
  } catch {
    return DEFAULT_SETTINGS
  }
}

export async function saveSettings(s: SettingsRecord): Promise<void> {
  const db = getDb()
  if (!db) return
  try {
    // Only write the slim shape — never re-persist legacy drill fields.
    const { id, commitKeyCode, commitKeyLabel, inputSource, activeProfileId } = s
    await db.settings.put({
      id,
      commitKeyCode,
      commitKeyLabel,
      inputSource,
      ...(activeProfileId !== undefined ? { activeProfileId } : {}),
    })
  } catch {
    /* ignore */
  }
}

let inFlightActive: Promise<ProfileRecord> | null = null

async function readLegacySettingsOverrides(): Promise<Partial<DrillConfig>> {
  const db = getDb()
  if (!db) return {}
  try {
    const row = (await db.settings.get('singleton')) as
      | (SettingsRecord & LegacySettingsFields)
      | undefined
    if (!row) return {}
    const overrides: Partial<DrillConfig> = {}
    const copyNumber = (k: keyof LegacySettingsFields, target: keyof DrillConfig) => {
      const v = row[k]
      if (typeof v === 'number') (overrides[target] as number) = v
    }
    const copyBool = (k: keyof LegacySettingsFields, target: keyof DrillConfig) => {
      const v = row[k]
      if (typeof v === 'boolean') (overrides[target] as boolean) = v
    }
    copyNumber('preCueMinMs', 'preCueMinMs')
    copyNumber('preCueMaxMs', 'preCueMaxMs')
    copyNumber('rounds', 'rounds')
    copyNumber('workMs', 'workMs')
    copyNumber('restMs', 'restMs')
    copyNumber('perFalseStartPenalty', 'perFalseStartPenalty')
    copyNumber('perHesitationPenalty', 'perHesitationPenalty')
    copyBool('penaltyCounterEnabled', 'penaltyCounterEnabled')
    copyBool('distanceAxisEnabled', 'distanceAxisEnabled')
    copyBool('audioToneEnabled', 'audioToneEnabled')
    copyBool('textOverlayEnabled', 'textOverlayEnabled')
    return overrides
  } catch {
    return {}
  }
}

/**
 * Resolve the user's active drill profile. On first run (or after migrating
 * from Phase 2/3) seeds a Default profile from whatever drill-config-shaped
 * fields the legacy SettingsRecord carried, then persists `activeProfileId`.
 *
 * Concurrent callers share one in-flight promise so we never double-seed under
 * React StrictMode's double-mount.
 */
export function loadActiveProfile(): Promise<ProfileRecord> {
  if (inFlightActive) return inFlightActive
  inFlightActive = (async () => {
    try {
      const settings = await loadSettings()
      if (settings.activeProfileId) {
        const existing = await getProfile(settings.activeProfileId)
        if (existing) return existing
      }
      const existing = await listProfiles()
      if (existing.length > 0) {
        const named =
          existing.find((p) => p.name === DEFAULT_PROFILE_NAME) ?? existing[0]
        await saveSettings({ ...settings, activeProfileId: named.id })
        return named
      }
      const overrides = await readLegacySettingsOverrides()
      const seed = buildDefaultProfile(overrides)
      await saveProfile(seed)
      await saveSettings({ ...settings, activeProfileId: seed.id })
      return seed
    } finally {
      inFlightActive = null
    }
  })()
  return inFlightActive
}

export async function setActiveProfile(id: string): Promise<void> {
  const settings = await loadSettings()
  await saveSettings({ ...settings, activeProfileId: id })
}

export { ensureAtLeastOneProfile }

import { useMemo } from 'react'
import { useSession, getSessionSummary } from '../store/session'
import { antiRhythmSignal, cueBreakdown } from '../engine/drill'
import { CUE_LIBRARY } from '../cues/library'
import type { CueId } from '../engine/types'

export function SummaryScreen() {
  const reps = useSession((s) => s.reps)
  const reset = useSession((s) => s.reset)
  const start = useSession((s) => s.start)
  const persistError = useSession((s) => s.persistError)
  const inputSource = useSession((s) => s.inputSource)
  const config = useSession((s) => s.config)
  const cleared = useSession((s) => s.cleared)

  const summary = useMemo(() => getSessionSummary(reps), [reps])
  const breakdown = useMemo(() => cueBreakdown(reps), [reps])
  const rhythm = useMemo(() => antiRhythmSignal(reps), [reps])

  const breakdownById = useMemo(() => {
    const m = new Map<CueId, (typeof breakdown)[number]>()
    for (const row of breakdown) m.set(row.cueId, row)
    return m
  }, [breakdown])

  return (
    <div className="screen summary">
      <h1>Session summary</h1>

      {persistError && (
        <div className="banner warn">
          Storage unavailable: {persistError}. Session was kept in memory only.
        </div>
      )}

      <p className="summary-meta">
        Input source: <strong>{inputSource}</strong>
        {config.penaltyCounterEnabled && (
          <> · Cleared {cleared} penalty rep{cleared === 1 ? '' : 's'}</>
        )}
      </p>

      <div className="stats">
        <Stat label="Reps" value={summary.reps} />
        <Stat label="Score" value={summary.score} />
        <Stat label="Correct" value={summary.correct} />
        <Stat label="False starts" value={summary.falseStarts} />
        <Stat label="Hesitations" value={summary.hesitations} />
        <Stat label="Late misses" value={summary.lateMisses} />
        <Stat
          label="Avg reaction"
          value={
            summary.avgReactionMs === null
              ? '—'
              : `${summary.avgReactionMs} ms`
          }
        />
      </div>

      <div className="rhythm-panel" aria-label="anti-rhythm signal">
        <h2>Rhythm pattern</h2>
        <p>{rhythm.narrative}</p>
      </div>

      <h2>By cue</h2>
      <table className="cue-table">
        <thead>
          <tr>
            <th>Cue</th>
            <th>Reps</th>
            <th>Correct</th>
            <th>FS</th>
            <th>Hes</th>
            <th>Late</th>
            <th>Avg RT</th>
            <th>Best-10 RT</th>
          </tr>
        </thead>
        <tbody>
          {CUE_LIBRARY.map((cue) => {
            const row = breakdownById.get(cue.id)
            if (!row) return null
            return (
              <tr key={cue.id}>
                <td>
                  {cue.label}{' '}
                  <span className="tag">{cue.isGo ? 'go' : 'no-go'}</span>
                </td>
                <td>{row.reps}</td>
                <td>{row.correct}</td>
                <td>{row.falseStarts}</td>
                <td>{row.hesitations}</td>
                <td>{row.lateMisses}</td>
                <td>{row.avgRtMs === null ? '—' : `${row.avgRtMs}`}</td>
                <td>
                  {row.best10AvgRtMs === null ? '—' : `${row.best10AvgRtMs}`}
                </td>
              </tr>
            )
          })}
        </tbody>
      </table>

      <div className="actions">
        <button
          type="button"
          className="primary"
          onClick={() => start(config, undefined, inputSource)}
        >
          Start another session
        </button>
        <button type="button" className="link" onClick={() => reset()}>
          Back to start
        </button>
      </div>
    </div>
  )
}

function Stat({ label, value }: { label: string; value: number | string }) {
  return (
    <div className="stat">
      <span className="stat-value">{value}</span>
      <span className="stat-label">{label}</span>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { listRecentSessions } from '../store/db'
import { useSession } from '../store/session'
import {
  DEFAULT_SETTINGS,
  loadActiveProfile,
  loadSettings,
  type SettingsRecord,
} from '../store/settings'
import type { ProfileRecord } from '../store/profiles'
import type { SessionRecord } from '../engine/types'

interface IdleScreenProps {
  onOpenSettings: () => void
}

export function IdleScreen({ onOpenSettings }: IdleScreenProps) {
  const start = useSession((s) => s.start)
  const [recent, setRecent] = useState<SessionRecord[]>([])
  const [settings, setSettings] = useState<SettingsRecord>(DEFAULT_SETTINGS)
  const [profile, setProfile] = useState<ProfileRecord | null>(null)

  useEffect(() => {
    void listRecentSessions(5).then(setRecent)
    void loadSettings().then(setSettings)
    void loadActiveProfile().then(setProfile)
  }, [])

  function handleStart() {
    void requestFullscreen()
    if (!profile) return
    start(profile.config, undefined, settings.inputSource)
  }

  return (
    <div className="screen idle">
      <h1>PointFight Reactor</h1>
      <p className="subtitle">First-beat go / no-go drill</p>

      {settings.inputSource === 'keyboard' && (
        <div className="banner info">
          Keyboard mode — foot pedal recommended for live drilling.
        </div>
      )}

      {profile && (
        <p className="active-profile">
          Profile: <strong>{profile.name}</strong>
        </p>
      )}

      <button
        className="primary"
        type="button"
        onClick={handleStart}
        disabled={!profile}
        autoFocus
      >
        Start drill
      </button>
      <p className="hint">
        Press <kbd>{settings.commitKeyLabel}</kbd> to commit. Press{' '}
        <kbd>Esc</kbd> to stop.
      </p>

      <button type="button" className="link" onClick={onOpenSettings}>
        Settings
      </button>

      {recent.length > 0 && (
        <div className="recent">
          <h2>Recent sessions</h2>
          <ul>
            {recent.map((s) => (
              <li key={s.id}>
                <span className="when">
                  {new Date(s.startedAt).toLocaleString()}
                </span>
                <span className="meta">
                  {s.repCount} reps · score {s.summary.score}
                  {s.summary.avgReactionMs !== null &&
                    ` · ${s.summary.avgReactionMs}ms avg`}
                  {s.inputSource && ` · ${s.inputSource}`}
                </span>
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  )
}

async function requestFullscreen(): Promise<void> {
  try {
    if (document.fullscreenElement) return
    await document.documentElement.requestFullscreen()
  } catch {
    /* user can run windowed; no-op */
  }
}

import { useEffect, useState } from 'react'
import {
  DEFAULT_SETTINGS,
  loadActiveProfile,
  loadSettings,
  saveSettings,
  setActiveProfile,
  type SettingsRecord,
} from '../store/settings'
import {
  buildDefaultProfile,
  deleteProfile,
  listProfiles,
  saveProfile,
  type ProfileRecord,
} from '../store/profiles'
import { validateDrillConfig } from '../engine/drill'
import { CUE_LIBRARY } from '../cues/library'
import {
  DEFAULT_DRILL_CONFIG,
  PRE_CUE_MAX_CEILING_MS,
  PRE_CUE_MIN_FLOOR_MS,
  type CueId,
  type DrillConfig,
  type InputSource,
  type RepResult,
} from '../engine/types'

interface SettingsScreenProps {
  onClose: () => void
}

const SCORE_FIELDS: { key: RepResult; label: string }[] = [
  { key: 'correct_go', label: 'Correct go' },
  { key: 'correct_no_go', label: 'Correct no-go' },
  { key: 'late', label: 'Late' },
  { key: 'hesitation', label: 'Hesitation' },
  { key: 'false_start', label: 'False start' },
]

export function SettingsScreen({ onClose }: SettingsScreenProps) {
  const [settings, setSettings] = useState<SettingsRecord>(DEFAULT_SETTINGS)
  const [profile, setProfile] = useState<ProfileRecord | null>(null)
  const [profiles, setProfiles] = useState<ProfileRecord[]>([])
  const [loaded, setLoaded] = useState(false)
  const [rebinding, setRebinding] = useState(false)
  const [errors, setErrors] = useState<string[]>([])

  useEffect(() => {
    let cancelled = false
    void Promise.all([loadSettings(), loadActiveProfile(), listProfiles()]).then(
      ([s, p, all]) => {
        if (cancelled) return
        setSettings(s)
        setProfile(p)
        setProfiles(all)
        setLoaded(true)
      },
    )
    return () => {
      cancelled = true
    }
  }, [])

  useEffect(() => {
    if (!rebinding) return
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        setRebinding(false)
        return
      }
      e.preventDefault()
      setSettings((prev) => ({
        ...prev,
        commitKeyCode: e.code,
        commitKeyLabel: humanizeKeyCode(e.code, e.key),
      }))
      setRebinding(false)
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [rebinding])

  function updateSettings<K extends keyof SettingsRecord>(
    key: K,
    value: SettingsRecord[K],
  ): void {
    setSettings((prev) => ({ ...prev, [key]: value }))
  }

  function updateConfig<K extends keyof DrillConfig>(
    key: K,
    value: DrillConfig[K],
  ): void {
    setProfile((prev) =>
      prev ? { ...prev, config: { ...prev.config, [key]: value } } : prev,
    )
  }

  function updateScoreWeight(result: RepResult, value: number): void {
    setProfile((prev) =>
      prev
        ? {
            ...prev,
            config: {
              ...prev.config,
              scoreWeights: { ...prev.config.scoreWeights, [result]: value },
            },
          }
        : prev,
    )
  }

  function toggleAllowedCue(cueId: CueId): void {
    setProfile((prev) => {
      if (!prev) return prev
      const current = prev.config.allowedCueIds ?? CUE_LIBRARY.map((c) => c.id)
      const set = new Set(current)
      if (set.has(cueId)) set.delete(cueId)
      else set.add(cueId)
      const next =
        set.size === CUE_LIBRARY.length ? null : Array.from(set)
      return { ...prev, config: { ...prev.config, allowedCueIds: next } }
    })
  }

  async function handleSave() {
    if (!profile) return
    const errs = validateDrillConfig(profile.config)
    if (errs.length > 0) {
      setErrors(errs.map((e) => `${e.field}: ${e.message}`))
      return
    }
    setErrors([])
    await saveProfile(profile)
    await saveSettings(settings)
    onClose()
  }

  async function handleSwitchProfile(id: string) {
    if (!id || id === profile?.id) return
    await setActiveProfile(id)
    const next = profiles.find((p) => p.id === id)
    if (next) setProfile(next)
    setSettings((prev) => ({ ...prev, activeProfileId: id }))
  }

  async function handleCreateProfile() {
    const name = prompt('New profile name?', `Profile ${profiles.length + 1}`)
    if (!name) return
    const base = profile
      ? { ...profile.config }
      : { ...DEFAULT_DRILL_CONFIG }
    const fresh = { ...buildDefaultProfile(base), name }
    await saveProfile(fresh)
    await setActiveProfile(fresh.id)
    setProfile(fresh)
    setProfiles((prev) => [...prev, fresh])
    setSettings((prev) => ({ ...prev, activeProfileId: fresh.id }))
  }

  async function handleRenameProfile() {
    if (!profile) return
    const name = prompt('Rename profile to:', profile.name)
    if (!name) return
    const renamed = { ...profile, name }
    await saveProfile(renamed)
    setProfile(renamed)
    setProfiles((prev) => prev.map((p) => (p.id === renamed.id ? renamed : p)))
  }

  async function handleDeleteProfile() {
    if (!profile) return
    if (profiles.length <= 1) {
      setErrors(['Cannot delete the only remaining profile.'])
      return
    }
    if (!confirm(`Delete profile "${profile.name}"?`)) return
    const remaining = profiles.filter((p) => p.id !== profile.id)
    await deleteProfile(profile.id)
    await setActiveProfile(remaining[0].id)
    setProfile(remaining[0])
    setProfiles(remaining)
    setSettings((prev) => ({ ...prev, activeProfileId: remaining[0].id }))
  }

  if (!loaded || !profile) {
    return (
      <div className="screen settings">
        <p>Loading settings…</p>
      </div>
    )
  }

  const config = profile.config
  const allowedCueIds = config.allowedCueIds ?? CUE_LIBRARY.map((c) => c.id)
  const allowedSet = new Set(allowedCueIds)

  return (
    <div className="screen settings">
      <header className="settings-header">
        <h1>Settings</h1>
        <button type="button" className="link" onClick={onClose}>
          Cancel
        </button>
      </header>

      <section className="settings-section">
        <h2>Profile</h2>
        <label>
          <span>Active profile</span>
          <select
            value={profile.id}
            onChange={(e) => void handleSwitchProfile(e.target.value)}
            aria-label="active profile"
          >
            {profiles.map((p) => (
              <option key={p.id} value={p.id}>
                {p.name}
              </option>
            ))}
          </select>
        </label>
        <div className="profile-actions">
          <button
            type="button"
            className="link"
            onClick={() => void handleCreateProfile()}
          >
            New profile
          </button>
          <button
            type="button"
            className="link"
            onClick={() => void handleRenameProfile()}
          >
            Rename
          </button>
          <button
            type="button"
            className="link"
            onClick={() => void handleDeleteProfile()}
          >
            Delete
          </button>
        </div>
      </section>

      <section className="settings-section">
        <h2>Input</h2>
        <label>
          <span>Input source</span>
          <select
            value={settings.inputSource}
            onChange={(e) =>
              updateSettings('inputSource', e.target.value as InputSource)
            }
          >
            <option value="keyboard">Keyboard (fallback / dev)</option>
            <option value="pedal">Foot pedal</option>
          </select>
        </label>
        <label>
          <span>Commit key</span>
          {rebinding ? (
            <span className="rebind-prompt">Press a key… (Esc to cancel)</span>
          ) : (
            <button
              type="button"
              className="rebind-button"
              onClick={() => setRebinding(true)}
              aria-label="Rebind commit key"
            >
              {settings.commitKeyLabel} ({settings.commitKeyCode})
            </button>
          )}
        </label>
        <p className="hint">
          USB foot pedals enumerate as keyboards. Configure your pedal to emit
          whichever key you bind here.
        </p>
      </section>

      <section className="settings-section">
        <h2>Rounds</h2>
        <label>
          <span>Round count</span>
          <input
            type="number"
            min={1}
            max={20}
            value={config.rounds}
            onChange={(e) =>
              updateConfig('rounds', Math.max(1, Number(e.target.value) || 1))
            }
          />
        </label>
        <label>
          <span>Work duration (seconds)</span>
          <input
            type="number"
            min={1}
            max={600}
            value={Math.round(config.workMs / 1000)}
            onChange={(e) =>
              updateConfig(
                'workMs',
                Math.max(1, Number(e.target.value) || 1) * 1000,
              )
            }
          />
        </label>
        <label>
          <span>Rest duration (seconds)</span>
          <input
            type="number"
            min={0}
            max={600}
            value={Math.round(config.restMs / 1000)}
            onChange={(e) =>
              updateConfig(
                'restMs',
                Math.max(0, Number(e.target.value) || 0) * 1000,
              )
            }
          />
        </label>
      </section>

      <section className="settings-section">
        <h2>Pre-cue delay</h2>
        <label>
          <span>Min (ms)</span>
          <input
            type="number"
            min={PRE_CUE_MIN_FLOOR_MS}
            max={PRE_CUE_MAX_CEILING_MS}
            step={100}
            value={config.preCueMinMs}
            onChange={(e) =>
              updateConfig('preCueMinMs', Number(e.target.value) || 0)
            }
          />
        </label>
        <label>
          <span>Max (ms)</span>
          <input
            type="number"
            min={PRE_CUE_MIN_FLOOR_MS}
            max={PRE_CUE_MAX_CEILING_MS}
            step={100}
            value={config.preCueMaxMs}
            onChange={(e) =>
              updateConfig('preCueMaxMs', Number(e.target.value) || 0)
            }
          />
        </label>
        <p className="hint">
          Range {PRE_CUE_MIN_FLOOR_MS}–{PRE_CUE_MAX_CEILING_MS} ms.
        </p>
      </section>

      <section className="settings-section">
        <h2>Choice-RT thresholds</h2>
        <label>
          <span>Hesitation threshold (ms)</span>
          <input
            type="number"
            min={100}
            max={2000}
            step={50}
            value={config.hesitationThresholdMs}
            onChange={(e) =>
              updateConfig(
                'hesitationThresholdMs',
                Number(e.target.value) || 0,
              )
            }
          />
        </label>
        <label>
          <span>Late threshold (ms)</span>
          <input
            type="number"
            min={100}
            max={3000}
            step={50}
            value={config.lateThresholdMs}
            onChange={(e) =>
              updateConfig('lateThresholdMs', Number(e.target.value) || 0)
            }
          />
        </label>
        <label>
          <span>Response window (ms)</span>
          <input
            type="number"
            min={100}
            max={5000}
            step={50}
            value={config.responseWindowMs}
            onChange={(e) =>
              updateConfig('responseWindowMs', Number(e.target.value) || 0)
            }
          />
        </label>
        <p className="hint">
          hesitation &lt; late &lt; response-window. Defaults 450 / 600 / 1200.
        </p>
      </section>

      <section className="settings-section">
        <h2>Cue subset</h2>
        <div className="cue-subset-grid">
          {CUE_LIBRARY.map((cue) => (
            <label key={cue.id} className="checkbox-row">
              <input
                type="checkbox"
                checked={allowedSet.has(cue.id)}
                onChange={() => toggleAllowedCue(cue.id)}
              />
              <span>{cue.label}</span>
            </label>
          ))}
        </div>
        <p className="hint">
          Uncheck to remove a cue from this profile. Must keep at least one go
          cue.
        </p>
      </section>

      <section className="settings-section">
        <h2>Scoring weights</h2>
        <div className="score-grid">
          {SCORE_FIELDS.map((f) => (
            <label key={f.key}>
              <span>{f.label}</span>
              <input
                type="number"
                step={1}
                value={config.scoreWeights[f.key]}
                onChange={(e) =>
                  updateScoreWeight(f.key, Number(e.target.value) || 0)
                }
              />
            </label>
          ))}
        </div>
      </section>

      <section className="settings-section">
        <h2>Visuals</h2>
        <label className="checkbox-row">
          <input
            type="checkbox"
            checked={config.distanceAxisEnabled}
            onChange={(e) =>
              updateConfig('distanceAxisEnabled', e.target.checked)
            }
          />
          <span>
            Enable distance axis (far / mid / in-range changes correct
            response)
          </span>
        </label>
        <label className="checkbox-row">
          <input
            type="checkbox"
            checked={config.audioToneEnabled}
            onChange={(e) => updateConfig('audioToneEnabled', e.target.checked)}
          />
          <span>Audio tone tracks distance (low → high pitch)</span>
        </label>
        <label className="checkbox-row">
          <input
            type="checkbox"
            checked={config.textOverlayEnabled}
            onChange={(e) =>
              updateConfig('textOverlayEnabled', e.target.checked)
            }
          />
          <span>Show text label overlay (learning mode)</span>
        </label>
      </section>

      <section className="settings-section">
        <h2>Penalty counter</h2>
        <label className="checkbox-row">
          <input
            type="checkbox"
            checked={config.penaltyCounterEnabled}
            onChange={(e) =>
              updateConfig('penaltyCounterEnabled', e.target.checked)
            }
          />
          <span>
            False starts and hesitations add reps to a during-rest clear-list
          </span>
        </label>
        {config.penaltyCounterEnabled && (
          <>
            <label>
              <span>Reps per false start</span>
              <input
                type="number"
                min={0}
                max={20}
                value={config.perFalseStartPenalty}
                onChange={(e) =>
                  updateConfig(
                    'perFalseStartPenalty',
                    Math.max(0, Number(e.target.value) || 0),
                  )
                }
              />
            </label>
            <label>
              <span>Reps per hesitation</span>
              <input
                type="number"
                min={0}
                max={20}
                value={config.perHesitationPenalty}
                onChange={(e) =>
                  updateConfig(
                    'perHesitationPenalty',
                    Math.max(0, Number(e.target.value) || 0),
                  )
                }
              />
            </label>
          </>
        )}
      </section>

      {errors.length > 0 && (
        <div className="banner warn">
          <ul>
            {errors.map((e) => (
              <li key={e}>{e}</li>
            ))}
          </ul>
        </div>
      )}

      <div className="actions">
        <button type="button" className="primary" onClick={() => void handleSave()}>
          Save
        </button>
      </div>
    </div>
  )
}

function humanizeKeyCode(code: string, key: string): string {
  if (code === 'Space') return 'Space'
  if (code.startsWith('Key')) return code.slice(3)
  if (code.startsWith('Digit')) return code.slice(5)
  if (code === 'Enter') return 'Enter'
  return key.length === 1 ? key.toUpperCase() : code
}

import { beforeEach, describe, expect, it } from 'vitest'
import { mulberry32 } from '../engine/rng'
import { useSession } from './session'
import { getDb } from './db'

function reset() {
  useSession.getState().reset()
}

async function clearDb() {
  const db = getDb()
  if (!db) return
  await db.reps.clear()
  await db.sessions.clear()
}

describe('useSession store', () => {
  beforeEach(async () => {
    reset()
    await clearDb()
  })

  it('transitions idle → waiting on start with a pre-selected cue', () => {
    useSession.getState().start({}, mulberry32(1))
    const s = useSession.getState()
    expect(s.phase).toBe('waiting')
    expect(s.sessionId).not.toBeNull()
    expect(s.current).not.toBeNull()
    expect(s.current?.cueShownAt).toBeNull()
    expect(s.reps).toEqual([])
  })

  it('press during waiting (pre-cue) records a false_start rep', () => {
    useSession.getState().start({}, mulberry32(2))
    const before = useSession.getState().reps.length
    useSession.getState().recordPress(performance.now())
    const after = useSession.getState()
    expect(after.reps.length).toBe(before + 1)
    expect(after.reps[after.reps.length - 1].result).toBe('false_start')
    expect(after.phase).toBe('feedback')
  })

  it('press after revealCue on a go cue records correct_go with reaction time', () => {
    useSession.getState().start(
      { goCueProbability: 1, hesitationThresholdMs: 600 },
      mulberry32(3),
    )
    useSession.getState().revealCue()
    const cueShownAt = useSession.getState().current?.cueShownAt as number
    useSession.getState().recordPress(cueShownAt + 200)
    const rep = useSession.getState().reps.at(-1)
    expect(rep?.result).toBe('correct_go')
    expect(rep?.reactionMs).toBe(200)
    expect(useSession.getState().phase).toBe('feedback')
  })

  it('finishWindow with no press on a go cue records late', () => {
    useSession.getState().start(
      { goCueProbability: 1 },
      mulberry32(4),
    )
    useSession.getState().revealCue()
    useSession.getState().finishWindow()
    const rep = useSession.getState().reps.at(-1)
    expect(rep?.result).toBe('late')
    expect(rep?.pressedAt).toBeNull()
  })

  it('finishWindow with no press on a no-go cue records correct_no_go', () => {
    useSession.getState().start(
      { goCueProbability: 0 },
      mulberry32(5),
    )
    useSession.getState().revealCue()
    useSession.getState().finishWindow()
    const rep = useSession.getState().reps.at(-1)
    expect(rep?.result).toBe('correct_no_go')
  })

  it('stop ends the drill', () => {
    useSession.getState().start({}, mulberry32(6))
    useSession.getState().stop()
    expect(useSession.getState().phase).toBe('ended')
  })

  it('persists session record incrementally so reps and session row stay in sync', async () => {
    useSession.getState().start(
      { goCueProbability: 1 },
      mulberry32(7),
    )
    const sessionId = useSession.getState().sessionId as string
    useSession.getState().revealCue()
    const cueShownAt = useSession.getState().current?.cueShownAt as number
    useSession.getState().recordPress(cueShownAt + 100)

    await new Promise((r) => setTimeout(r, 0))
    const db = getDb()
    if (!db) throw new Error('db not available in test')
    const stored = await db.sessions.get(sessionId)
    expect(stored?.repCount).toBe(1)
    expect(stored?.summary.correct).toBe(1)
    expect(stored?.endedAt).toBeNull()
  })

  it('acknowledgeFeedback after maxReps ends the drill', () => {
    useSession.getState().start(
      { goCueProbability: 1, maxReps: 1 },
      mulberry32(8),
    )
    useSession.getState().revealCue()
    const cueShownAt = useSession.getState().current?.cueShownAt as number
    useSession.getState().recordPress(cueShownAt + 50)
    useSession.getState().acknowledgeFeedback()
    expect(useSession.getState().phase).toBe('ended')
  })

  it('acknowledgeFeedback transitions to rest when work time is up and more rounds remain', () => {
    useSession.getState().start(
      { goCueProbability: 1, rounds: 2, workMs: 0, restMs: 1000 },
      mulberry32(9),
    )
    useSession.getState().revealCue()
    const cueShownAt = useSession.getState().current?.cueShownAt as number
    useSession.getState().recordPress(cueShownAt + 50)
    useSession.getState().acknowledgeFeedback()
    const s = useSession.getState()
    expect(s.phase).toBe('rest')
    expect(s.restEndAt).not.toBeNull()
    expect(s.roundIndex).toBe(0)
  })

  it('nextRound from rest increments roundIndex and starts new work period', () => {
    useSession.getState().start(
      { goCueProbability: 1, rounds: 3, workMs: 0, restMs: 0 },
      mulberry32(10),
    )
    useSession.getState().revealCue()
    const cueShownAt = useSession.getState().current?.cueShownAt as number
    useSession.getState().recordPress(cueShownAt + 50)
    useSession.getState().acknowledgeFeedback()
    expect(useSession.getState().phase).toBe('rest')

    useSession.getState().nextRound()
    const s = useSession.getState()
    expect(s.roundIndex).toBe(1)
    expect(s.phase).toBe('waiting')
    expect(s.restEndAt).toBeNull()
    expect(s.workEndAt).not.toBeNull()
  })

  it('acknowledgeFeedback after final round ends the drill instead of resting', () => {
    useSession.getState().start(
      { goCueProbability: 1, rounds: 1, workMs: 0, restMs: 1000 },
      mulberry32(11),
    )
    useSession.getState().revealCue()
    const cueShownAt = useSession.getState().current?.cueShownAt as number
    useSession.getState().recordPress(cueShownAt + 50)
    useSession.getState().acknowledgeFeedback()
    expect(useSession.getState().phase).toBe('ended')
  })

  it('stamps roundIndex and inputSource on each rep', () => {
    useSession.getState().start(
      { goCueProbability: 1, rounds: 2, workMs: 0, restMs: 0 },
      mulberry32(12),
      'pedal',
    )
    useSession.getState().revealCue()
    let cueShownAt = useSession.getState().current?.cueShownAt as number
    useSession.getState().recordPress(cueShownAt + 50)
    expect(useSession.getState().reps.at(-1)?.roundIndex).toBe(0)
    expect(useSession.getState().reps.at(-1)?.inputSource).toBe('pedal')

    useSession.getState().acknowledgeFeedback()
    useSession.getState().nextRound()
    useSession.getState().revealCue()
    cueShownAt = useSession.getState().current?.cueShownAt as number
    useSession.getState().recordPress(cueShownAt + 50)
    expect(useSession.getState().reps.at(-1)?.roundIndex).toBe(1)
  })

  it('stamps a distance on the rep when distance axis is enabled', () => {
    useSession.getState().start(
      { distanceAxisEnabled: true, maxReps: 1 },
      mulberry32(20),
    )
    useSession.getState().revealCue()
    const cueShownAt = useSession.getState().current?.cueShownAt as number
    useSession.getState().recordPress(cueShownAt + 80)
    const rep = useSession.getState().reps.at(-1)
    expect(rep?.distance).toBeDefined()
    expect(['far', 'mid', 'in_range']).toContain(rep?.distance)
  })

  it('omits distance when distance axis is disabled', () => {
    useSession.getState().start(
      { goCueProbability: 1, maxReps: 1 },
      mulberry32(21),
    )
    useSession.getState().revealCue()
    const cueShownAt = useSession.getState().current?.cueShownAt as number
    useSession.getState().recordPress(cueShownAt + 80)
    const rep = useSession.getState().reps.at(-1)
    expect(rep?.distance).toBeUndefined()
  })

  it('clearPenalty increments cleared and persists', async () => {
    useSession.getState().start({}, mulberry32(13))
    expect(useSession.getState().cleared).toBe(0)
    useSession.getState().clearPenalty()
    useSession.getState().clearPenalty()
    expect(useSession.getState().cleared).toBe(2)

    await new Promise((r) => setTimeout(r, 0))
    const db = getDb()
    if (!db) throw new Error('db unavailable')
    const sessionId = useSession.getState().sessionId as string
    const stored = await db.sessions.get(sessionId)
    expect(stored?.cleared).toBe(2)
  })
})

