333	export function summarize(reps: RepRecord[]): SessionSummary {
334	  const reactionTimes = reps
335	    .filter((r) => r.result === 'correct_go' && r.reactionMs !== null)
336	    .map((r) => r.reactionMs as number)
337	
338	  const avgReactionMs =
339	    reactionTimes.length === 0
340	      ? null
341	      : Math.round(
342	          reactionTimes.reduce((a, b) => a + b, 0) / reactionTimes.length,
343	        )
344	
345	  return {
346	    reps: reps.length,
347	    correct: reps.filter(
348	      (r) => r.result === 'correct_go' || r.result === 'correct_no_go',
349	    ).length,
350	    falseStarts: reps.filter((r) => r.result === 'false_start').length,
351	    lateMisses: reps.filter((r) => r.result === 'late').length,
352	    hesitations: reps.filter((r) => r.result === 'hesitation').length,
353	    score: reps.reduce((a, r) => a + r.score, 0),
354	    avgReactionMs,
355	  }
356	}
