    reps.push(make('steps_in', true, 'correct_go'))
    reps.push(make('steps_in', true, 'false_start'))   // streak before = 3 → 3+
    const stats = antiRhythmSignal(reps)
    expect(stats.narrative).toMatch(/3\+ consecutive go cues/)
  })
})

