file.content:
:root {
  --gym-bg: #08090c;
  --gym-fg: #f8fafc;
  --gym-muted: #94a3b8;
  --gym-accent: #38bdf8;
  --gym-go: #16a34a;
  --gym-no-go: #f59e0b;
  --gym-correct: #16a34a;
  --gym-bad: #dc2626;
  --gym-warn: #f59e0b;
  --gym-neutral: #1f2937;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
  background: var(--gym-bg);
  color: var(--gym-fg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

#root {
  display: flex;
  flex-direction: column;
  width: 100%;
  max-width: none;
  text-align: left;
  border: none;
}

.screen {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 32px;
  box-sizing: border-box;
}

button.primary {
  font-size: 2.2rem;
  font-weight: 700;
  padding: 1.2rem 2.6rem;
  border-radius: 14px;
  border: none;
  background: var(--gym-accent);
  color: #04121a;
  cursor: pointer;
  letter-spacing: 0.5px;
}
button.primary:hover {
  filter: brightness(1.1);
}
button.primary:focus-visible {
  outline: 4px solid var(--gym-fg);
  outline-offset: 4px;
}

button.link {
  background: transparent;
  color: var(--gym-muted);
  border: 1px solid var(--gym-neutral);
  padding: 0.5rem 1rem;
  border-radius: 8px;
  cursor: pointer;
  font-size: 1rem;
}

kbd {
  display: inline-block;
  padding: 0.1em 0.55em;
  border-radius: 6px;
  border: 1px solid var(--gym-neutral);
  background: #111827;
  font-family: ui-monospace, monospace;
  font-size: 0.95em;
}

/* ---- Idle screen ---- */
.screen.idle {
  gap: 1.8rem;
  text-align: center;
}
.screen.idle h1 {
  margin: 0;
  font-size: clamp(2.8rem, 6vw, 4.6rem);
  letter-spacing: -1.5px;
}
.screen.idle .subtitle {
  margin: -0.6rem 0 0;
  color: var(--gym-muted);
  font-size: 1.4rem;
}
.screen.idle .hint {
  color: var(--gym-muted);
  font-size: 1.1rem;
}
.recent {
  width: min(640px, 100%);
  margin-top: 1rem;
  border-top: 1px solid var(--gym-neutral);
  padding-top: 1rem;
  text-align: left;
}
.recent h2 {
  font-size: 1rem;
  font-weight: 600;
  color: var(--gym-muted);
  text-transform: uppercase;
  letter-spacing: 1px;
  margin: 0 0 0.6rem;
}
.recent ul {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}
.recent li {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  font-size: 1rem;
  padding: 0.4rem 0.6rem;
  background: var(--gym-neutral);
  border-radius: 6px;
}
.recent .when {
  color: var(--gym-fg);
}
.recent .meta {
  color: var(--gym-muted);
}

/* ---- Trainer screen ---- */
.screen.trainer {
  position: relative;
  padding: 0;
  transition: background-color 80ms linear;
}
.screen.trainer .hud {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem 1.5rem;
  font-size: 1.1rem;
  color: var(--gym-muted);
  z-index: 2;
}
.screen.trainer .stage {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
}

.ready,
.cue,
.feedback {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.2rem;
}

.ready-label {
  font-size: clamp(2rem, 5vw, 3.4rem);
  letter-spacing: 6px;
  color: var(--gym-muted);
  text-transform: uppercase;
}
.ready .dot,
.motion-pulse {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--gym-muted);
  animation: pulse 1.4s ease-in-out infinite;
}
.motion-pulse {
  width: 96px;
  height: 96px;
  background: radial-gradient(
    circle at center,
    rgba(56, 189, 248, 0.55) 0%,
    rgba(56, 189, 248, 0) 70%
