const SPARK_W = 120
const SPARK_H = 28
const SPARK_PAD = 2

function SparkRow({
  label,
  series,
  kind,
}: {
  label: string
  series: (number | null)[]
  kind: 'ms-lower-better' | 'rate-lower-better'
}) {
