  const stepX = (SPARK_W - SPARK_PAD * 2) / (series.length - 1)
  const points = series
    .map((v, i) => {
      if (v === null) return null
      const x = SPARK_PAD + i * stepX
      const y =
        SPARK_PAD + ((max - v) / span) * (SPARK_H - SPARK_PAD * 2)
      return `${x.toFixed(1)},${y.toFixed(1)}`
    })
    .filter((p): p is string => p !== null)
