        <SparkRow
          label="Best-10 RT (ms)"
          series={best10Series}
          kind="ms-lower-better"
        />
        <SparkRow
          label="False-start rate"
          series={fsSeries}
          kind="rate-lower-better"
        />
        <SparkRow
          label="Hesitation rate"
          series={hesSeries}
          kind="rate-lower-better"
        />
      </div>
      <table className="cue-table trend-table">
        <thead>
          <tr>
            <th>Session</th>
            <th>Reps</th>
            <th>Avg RT</th>
            <th>Best-10</th>
            <th>FS rate</th>
            <th>Hes rate</th>
            <th>Score</th>
          </tr>
        </thead>
        <tbody>
          {trend.map((t) => (
