      inner.set(r.sessionId, r)
      m.set(r.cueId, inner)
    }
    return m
  }, [trendRows])
  const aggById = useMemo(() => {
    const m = new Map<CueId, CueAggregateRow>()
    for (const a of aggregates) m.set(a.cueId, a)
