                <td>{agg.avgRtMs === null ? '—' : `${agg.avgRtMs}`}</td>
                <td>
                  {agg.best10AvgRtMs === null ? '—' : `${agg.best10AvgRtMs}`}
                </td>
                <td>{fmtPct(agg.errorRate)}</td>
                <td>
                  <Spark series={perSession} kind="ms-lower-better" />
