import { describe, expect, it } from 'vitest'
import {
  compareSessions,
  cueAggregate,
  cueTrend,
  pickTaperCues,
  sessionTrend,
} from './analytics'
import type { CueId, RepRecord, RepResult, SessionRecord } from './types'

let nextRepId = 0
function rep(
  sessionId: string,
  cueId: CueId,
  result: RepResult,
  reactionMs: number | null,
  isGo: boolean,
  score = 0,
): RepRecord {
  return {
    id: `r-${++nextRepId}`,
    sessionId,
    cueId,
    isGo,
    result,
    reactionMs,
    score,
    cueShownAt: 0,
    pressedAt: null,
    roundIndex: 0,
    inputSource: 'keyboard',
  }
}

function session(
  id: string,
  startedAt: number,
  reps: RepRecord[],
  scoreWeights?: SessionRecord['summary']['score'],
): { rec: SessionRecord; reps: RepRecord[] } {
  const correct = reps.filter(
    (r) => r.result === 'correct_go' || r.result === 'correct_no_go',
  ).length
  const fs = reps.filter((r) => r.result === 'false_start').length
  const hes = reps.filter((r) => r.result === 'hesitation').length
  const lateMisses = reps.filter((r) => r.result === 'late').length
  const goTimes = reps
    .filter((r) => r.result === 'correct_go' && r.reactionMs !== null)
    .map((r) => r.reactionMs as number)
  const avg =
    goTimes.length === 0
      ? null
      : Math.round(goTimes.reduce((a, b) => a + b, 0) / goTimes.length)
  return {
    rec: {
      id,
      startedAt,
      endedAt: startedAt + 60_000,
      drillType: 'first_beat_go_no_go',
      repCount: reps.length,
      summary: {
        reps: reps.length,
        correct,
        falseStarts: fs,
        lateMisses,
        hesitations: hes,
        score: reps.reduce((a, r) => a + r.score, 0) + (scoreWeights ?? 0),
        avgReactionMs: avg,
      },
    },
    reps,
  }
}

// ----- sessionTrend -----

describe('sessionTrend', () => {
  it('returns one trend point per session ordered by startedAt ascending', () => {
    const a = session('A', 1000, [
      rep('A', 'steps_in', 'correct_go', 300, true),
      rep('A', 'steps_in', 'correct_go', 400, true),
      rep('A', 'no_go_bait', 'correct_no_go', null, false),
    ])
    const b = session('B', 2000, [
      rep('B', 'steps_in', 'hesitation', 500, true),
      rep('B', 'steps_in', 'false_start', null, true),
    ])
    const map = new Map([
      [a.rec.id, a.reps],
      [b.rec.id, b.reps],
    ])
    // Pass sessions in reverse order — helper should sort ascending.
    const trend = sessionTrend([b.rec, a.rec], map)
    expect(trend.map((t) => t.sessionId)).toEqual(['A', 'B'])
    expect(trend[0].avgRtMs).toBe(350)
    expect(trend[0].best10AvgRtMs).toBe(350)
    expect(trend[0].falseStartRate).toBe(0)
    expect(trend[0].hesitationRate).toBe(0)
    expect(trend[1].falseStartRate).toBeCloseTo(0.5, 5)
    expect(trend[1].hesitationRate).toBeCloseTo(0.5, 5)
    expect(trend[1].avgRtMs).toBeNull()
  })

  it('filters out sessions with zero reps from the trend', () => {
    const empty = session('E', 1000, [])
    const real = session('R', 2000, [
      rep('R', 'steps_in', 'correct_go', 250, true),
    ])
    const map = new Map([
      [empty.rec.id, empty.reps],
      [real.rec.id, real.reps],
    ])
    const trend = sessionTrend([empty.rec, real.rec], map)
    expect(trend.map((t) => t.sessionId)).toEqual(['R'])
  })
})

// ----- cueTrend -----

describe('cueTrend', () => {
  it('produces one row per (session, observed cue) pair with error rate and avg RT', () => {
    const a = session('A', 1000, [
      rep('A', 'steps_in', 'correct_go', 300, true),
      rep('A', 'steps_in', 'correct_go', 400, true),
      rep('A', 'steps_in', 'hesitation', 700, true),
      rep('A', 'no_go_bait', 'correct_no_go', null, false),
    ])
    const map = new Map([[a.rec.id, a.reps]])
    const trend = cueTrend([a.rec], map)
    const steps = trend.find((r) => r.cueId === 'steps_in')
    const bait = trend.find((r) => r.cueId === 'no_go_bait')
    expect(steps?.reps).toBe(3)
    expect(steps?.avgRtMs).toBe(350)
    expect(steps?.errorRate).toBeCloseTo(1 / 3, 5)
    expect(bait?.errorRate).toBe(0)
    expect(bait?.avgRtMs).toBeNull()
  })
})

// ----- cueAggregate -----

describe('cueAggregate', () => {
  it('rolls up reps across sessions, counting distinct sessions per cue', () => {
    const a = session('A', 1000, [
      rep('A', 'steps_in', 'correct_go', 300, true),
      rep('A', 'steps_in', 'correct_go', 400, true),
    ])
    const b = session('B', 2000, [
      rep('B', 'steps_in', 'correct_go', 500, true),
      rep('B', 'no_go_bait', 'false_start', null, false),
      rep('B', 'no_go_bait', 'correct_no_go', null, false),
    ])
    const map = new Map([
      [a.rec.id, a.reps],
      [b.rec.id, b.reps],
    ])
    const agg = cueAggregate([a.rec, b.rec], map)
    const steps = agg.find((r) => r.cueId === 'steps_in')
    const bait = agg.find((r) => r.cueId === 'no_go_bait')
    expect(steps?.reps).toBe(3)
    expect(steps?.sessions).toBe(2)
    expect(steps?.avgRtMs).toBe(400)
    expect(steps?.best10AvgRtMs).toBe(400)
    expect(steps?.goWeakness).not.toBeNull()
    expect(steps?.noGoWeakness).toBeNull()
    expect(bait?.reps).toBe(2)
    expect(bait?.sessions).toBe(1)
    expect(bait?.errorRate).toBe(0.5)
    expect(bait?.goWeakness).toBeNull()
    expect(bait?.noGoWeakness).toBe(0.5)
  })
})

// ----- pickTaperCues -----

describe('pickTaperCues', () => {
  it('returns the worst go cues and worst no-go cues with the default 70/30 split (k=3 → 2 go + 1 no-go)', () => {
    const sessions: SessionRecord[] = []
    const reps: RepRecord[] = []
    function addSession(id: string, startedAt: number, perCue: [CueId, number, boolean, RepResult][]) {
      const sReps: RepRecord[] = []
      for (const [cueId, rt, isGo, result] of perCue) {
        sReps.push(rep(id, cueId, result, rt, isGo))
      }
      sessions.push({
        id,
        startedAt,
        endedAt: startedAt + 60_000,
        drillType: 'first_beat_go_no_go',
        repCount: sReps.length,
        summary: {
          reps: sReps.length,
          correct: sReps.filter(
            (r) => r.result === 'correct_go' || r.result === 'correct_no_go',
          ).length,
          falseStarts: 0,
          lateMisses: 0,
          hesitations: 0,
          score: 0,
          avgReactionMs: null,
        },
      })
      reps.push(...sReps)
    }
    // Each cue must appear in ≥2 sessions with ≥5 total reps to be eligible.
    // steps_in: fast and clean (200ms avg) → should NOT be picked.
    // retreats: slow (500ms avg) — picked first from go pool.
    // freezes: medium (400ms avg) with errors — second pick from go pool.
    // drops_lead_hand: borderline (350ms, clean) — fills if go-pool empties.
    // no_go_bait: high false-start rate (0.4) — picked from no-go pool.
    // fake_steps: low false-start rate (0.1) — not picked.
    addSession('s1', 1000, [
      ['steps_in', 200, true, 'correct_go'],
      ['steps_in', 200, true, 'correct_go'],
      ['steps_in', 200, true, 'correct_go'],
      ['retreats', 500, true, 'correct_go'],
      ['retreats', 500, true, 'correct_go'],
      ['retreats', 500, true, 'correct_go'],
      ['freezes', 400, true, 'correct_go'],
      ['freezes', 400, true, 'correct_go'],
      ['freezes', null, true, 'late'],
      ['drops_lead_hand', 350, true, 'correct_go'],
      ['drops_lead_hand', 350, true, 'correct_go'],
      ['drops_lead_hand', 350, true, 'correct_go'],
      ['no_go_bait', null, false, 'false_start'],
      ['no_go_bait', null, false, 'false_start'],
      ['no_go_bait', null, false, 'correct_no_go'],
      ['no_go_bait', null, false, 'correct_no_go'],
      ['no_go_bait', null, false, 'correct_no_go'],
      ['fake_steps', null, false, 'correct_no_go'],
      ['fake_steps', null, false, 'correct_no_go'],
      ['fake_steps', null, false, 'correct_no_go'],
      ['fake_steps', null, false, 'correct_no_go'],
      ['fake_steps', null, false, 'correct_no_go'],
    ])
    // Same shape in session 2 to satisfy ≥2 sessions per cue.
    addSession('s2', 2000, [
      ['steps_in', 200, true, 'correct_go'],
      ['steps_in', 200, true, 'correct_go'],
      ['steps_in', 200, true, 'correct_go'],
      ['retreats', 500, true, 'correct_go'],
      ['retreats', 500, true, 'correct_go'],
      ['freezes', 400, true, 'correct_go'],
      ['freezes', 400, true, 'correct_go'],
      ['drops_lead_hand', 350, true, 'correct_go'],
      ['drops_lead_hand', 350, true, 'correct_go'],
      ['no_go_bait', null, false, 'false_start'],
      ['no_go_bait', null, false, 'correct_no_go'],
      ['no_go_bait', null, false, 'correct_no_go'],
      ['fake_steps', null, false, 'correct_no_go'],
      ['fake_steps', null, false, 'correct_no_go'],
      ['fake_steps', null, false, 'correct_no_go'],
    ])
    const map = new Map<string, RepRecord[]>()
    for (const r of reps) {
      const list = map.get(r.sessionId) ?? []
      list.push(r)
      map.set(r.sessionId, list)
    }
    const agg = cueAggregate(sessions, map)
    const rec = pickTaperCues(agg, 3)
    expect(rec.cueIds).toHaveLength(3)
    // top-2 weakest go cues (by weakness desc): retreats (0.5 RT + 0 errors)
    // then freezes (0.4 RT + 1/5 errors).
    expect(rec.cueIds).toContain('retreats')
    expect(rec.cueIds).toContain('freezes')
    // top-1 weakest no-go cue: no_go_bait (errorRate 0.375 ≈ 3/8) > fake_steps (0)
    expect(rec.cueIds).toContain('no_go_bait')
    expect(rec.cueIds).not.toContain('fake_steps')
    expect(rec.cueIds).not.toContain('steps_in')
    expect(rec.reason).toMatch(/slowest|weakest/i)
  })

  it('drops cues with fewer than 5 reps across the window', () => {
    const a = session('A', 1000, [
      rep('A', 'steps_in', 'correct_go', 500, true),
      rep('A', 'steps_in', 'correct_go', 500, true),
      rep('A', 'steps_in', 'correct_go', 500, true),
      rep('A', 'steps_in', 'correct_go', 500, true),
    ])
    const map = new Map([[a.rec.id, a.reps]])
    const agg = cueAggregate([a.rec], map)
    const rec = pickTaperCues(agg, 3)
    expect(rec.cueIds).toEqual([])
    expect(rec.reason).toMatch(/not enough data/i)
  })

  it('drops cues seen in fewer than 2 sessions', () => {
    const a = session('A', 1000, [
      rep('A', 'steps_in', 'correct_go', 500, true),
      rep('A', 'steps_in', 'correct_go', 500, true),
      rep('A', 'steps_in', 'correct_go', 500, true),
      rep('A', 'steps_in', 'correct_go', 500, true),
      rep('A', 'steps_in', 'correct_go', 500, true),
    ])
    const map = new Map([[a.rec.id, a.reps]])
    const agg = cueAggregate([a.rec], map)
    const rec = pickTaperCues(agg, 3)
    expect(rec.cueIds).toEqual([])
  })

  it('falls back to the other pool when one pool is empty', () => {
    // All eligible cues are no-go — picker fills all 3 from no-go pool.
    const buildSession = (id: string, t: number) => {
      const sReps: RepRecord[] = []
      for (const cue of ['no_go_bait', 'fake_steps'] as CueId[]) {
        for (let i = 0; i < 5; i++) {
          sReps.push(rep(id, cue, 'false_start', null, false))
        }
      }
      return session(id, t, sReps)
    }
    const a = buildSession('A', 1000)
    const b = buildSession('B', 2000)
    const map = new Map([
      [a.rec.id, a.reps],
      [b.rec.id, b.reps],
    ])
    const agg = cueAggregate([a.rec, b.rec], map)
    const rec = pickTaperCues(agg, 3)
    expect(rec.cueIds).toContain('no_go_bait')
    expect(rec.cueIds).toContain('fake_steps')
    expect(rec.cueIds.length).toBeLessThanOrEqual(2) // only two no-go cues exist
  })

  it('ties on weakness break by cueId ascending for determinism', () => {
    // Two go cues with identical weakness — picker returns the one with the
    // lexicographically smaller cueId first.
    const buildSession = (id: string, t: number) => {
      const sReps: RepRecord[] = []
      for (const cue of ['retreats', 'freezes'] as CueId[]) {
        for (let i = 0; i < 5; i++) {
          sReps.push(rep(id, cue, 'correct_go', 400, true))
        }
      }
      return session(id, t, sReps)
    }
    const a = buildSession('A', 1000)
    const b = buildSession('B', 2000)
    const map = new Map([
      [a.rec.id, a.reps],
      [b.rec.id, b.reps],
    ])
    const agg = cueAggregate([a.rec, b.rec], map)
    const rec = pickTaperCues(agg, 1)
    expect(rec.cueIds).toEqual(['freezes'])
  })
})

// ----- compareSessions -----

describe('compareSessions', () => {
  it('classifies a cue measured in both sessions as both_measured with delta-RT', () => {
    const a = session('A', 1000, [
      rep('A', 'steps_in', 'correct_go', 400, true),
      rep('A', 'steps_in', 'correct_go', 400, true),
    ])
    const b = session('B', 2000, [
      rep('B', 'steps_in', 'correct_go', 300, true),
      rep('B', 'steps_in', 'correct_go', 300, true),
    ])
    const delta = compareSessions(a.rec, b.rec, a.reps, b.reps)
    const row = delta.perCue.find((r) => r.cueId === 'steps_in')
    expect(row?.classification).toBe('both_measured')
    expect(row?.deltaAvgRtMs).toBe(-100)
    expect(row?.deltaErrorRate).toBe(0)
  })

  it('flags both_error_only when one side has reps but zero correct_go', () => {
    const a = session('A', 1000, [
      rep('A', 'steps_in', 'correct_go', 400, true),
      rep('A', 'steps_in', 'correct_go', 400, true),
    ])
    const b = session('B', 2000, [
      rep('B', 'steps_in', 'false_start', null, true),
      rep('B', 'steps_in', 'late', null, true),
    ])
    const delta = compareSessions(a.rec, b.rec, a.reps, b.reps)
    const row = delta.perCue.find((r) => r.cueId === 'steps_in')
    expect(row?.classification).toBe('both_error_only')
    expect(row?.deltaAvgRtMs).toBeNull()
    expect(row?.deltaErrorRate).toBe(1) // 1.0 errors - 0 errors
  })

  it('marks cues present only in candidate as candidate_only', () => {
    const a = session('A', 1000, [
      rep('A', 'steps_in', 'correct_go', 300, true),
    ])
    const b = session('B', 2000, [
      rep('B', 'steps_in', 'correct_go', 300, true),
      rep('B', 'retreats', 'correct_go', 500, true),
    ])
    const delta = compareSessions(a.rec, b.rec, a.reps, b.reps)
    const row = delta.perCue.find((r) => r.cueId === 'retreats')
    expect(row?.classification).toBe('candidate_only')
  })

  it('marks cues present only in baseline as baseline_only', () => {
    const a = session('A', 1000, [
      rep('A', 'steps_in', 'correct_go', 300, true),
      rep('A', 'retreats', 'correct_go', 500, true),
    ])
    const b = session('B', 2000, [
      rep('B', 'steps_in', 'correct_go', 300, true),
    ])
    const delta = compareSessions(a.rec, b.rec, a.reps, b.reps)
    const row = delta.perCue.find((r) => r.cueId === 'retreats')
    expect(row?.classification).toBe('baseline_only')
  })

  it('suppresses deltaScore (returns null) when the two summary scoreWeights differ', () => {
    // Forge two sessions whose per-rep `score` was computed under different
    // weights: A's correct_go = +1, B's correct_go = +2.
    const a = session('A', 1000, [
      rep('A', 'steps_in', 'correct_go', 300, true, 1),
      rep('A', 'steps_in', 'correct_go', 300, true, 1),
    ])
    const b = session('B', 2000, [
      rep('B', 'steps_in', 'correct_go', 300, true, 2),
      rep('B', 'steps_in', 'correct_go', 300, true, 2),
    ])
    const delta = compareSessions(a.rec, b.rec, a.reps, b.reps)
    expect(delta.weightsDiffer).toBe(true)
    expect(delta.deltaScore).toBeNull()
  })
})

import { useEffect, useState } from 'react'
import {
  DEFAULT_SETTINGS,
  loadActiveProfile,
  loadSettings,
  saveSettings,
  setActiveProfile,
  type SettingsRecord,
} from '../store/settings'
import {
  buildDefaultProfile,
  deleteProfile,
  listProfiles,
  saveProfile,
  type ProfileRecord,
} from '../store/profiles'
import { validateDrillConfig } from '../engine/drill'
import { CUE_LIBRARY } from '../cues/library'
import {
  DEFAULT_DRILL_CONFIG,
  PRE_CUE_MAX_CEILING_MS,
  PRE_CUE_MIN_FLOOR_MS,
  type CueId,
  type DrillConfig,
  type InputSource,
  type RepResult,
} from '../engine/types'

interface SettingsScreenProps {
  onClose: () => void
}

const SCORE_FIELDS: { key: RepResult; label: string }[] = [
  { key: 'correct_go', label: 'Correct go' },
  { key: 'correct_no_go', label: 'Correct no-go' },
  { key: 'late', label: 'Late' },
  { key: 'hesitation', label: 'Hesitation' },
  { key: 'false_start', label: 'False start' },
]

export function SettingsScreen({ onClose }: SettingsScreenProps) {
  const [settings, setSettings] = useState<SettingsRecord>(DEFAULT_SETTINGS)
  const [profile, setProfile] = useState<ProfileRecord | null>(null)
  const [profiles, setProfiles] = useState<ProfileRecord[]>([])
  const [loaded, setLoaded] = useState(false)
  const [rebinding, setRebinding] = useState(false)
  const [errors, setErrors] = useState<string[]>([])

  useEffect(() => {
    let cancelled = false
    void Promise.all([loadSettings(), loadActiveProfile(), listProfiles()]).then(
      ([s, p, all]) => {
        if (cancelled) return
        setSettings(s)
        setProfile(p)
        setProfiles(all)
        setLoaded(true)
      },
    )
    return () => {
      cancelled = true
    }
  }, [])

  useEffect(() => {
    if (!rebinding) return
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        setRebinding(false)
        return
      }
      e.preventDefault()
      setSettings((prev) => ({
        ...prev,
        commitKeyCode: e.code,
        commitKeyLabel: humanizeKeyCode(e.code, e.key),
      }))
      setRebinding(false)
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [rebinding])

  function updateSettings<K extends keyof SettingsRecord>(
    key: K,
    value: SettingsRecord[K],
  ): void {
    setSettings((prev) => ({ ...prev, [key]: value }))
  }

  function updateConfig<K extends keyof DrillConfig>(
    key: K,
    value: DrillConfig[K],
  ): void {
    setProfile((prev) =>
      prev ? { ...prev, config: { ...prev.config, [key]: value } } : prev,
    )
  }

  function updateScoreWeight(result: RepResult, value: number): void {
    setProfile((prev) =>
      prev
        ? {
            ...prev,
            config: {
              ...prev.config,
              scoreWeights: { ...prev.config.scoreWeights, [result]: value },
            },
          }
        : prev,
    )
  }

  function toggleAllowedCue(cueId: CueId): void {
    setProfile((prev) => {
      if (!prev) return prev
      const current = prev.config.allowedCueIds ?? CUE_LIBRARY.map((c) => c.id)
      const set = new Set(current)
      if (set.has(cueId)) set.delete(cueId)
      else set.add(cueId)
      const next =
        set.size === CUE_LIBRARY.length ? null : Array.from(set)
      return { ...prev, config: { ...prev.config, allowedCueIds: next } }
    })
  }

  async function handleSave() {
    if (!profile) return
    const errs = validateDrillConfig(profile.config)
    if (errs.length > 0) {
      setErrors(errs.map((e) => `${e.field}: ${e.message}`))
      return
    }
    setErrors([])
    await saveProfile(profile)
    await saveSettings(settings)
    onClose()
  }

  async function handleSwitchProfile(id: string) {
    if (!id || id === profile?.id) return
    await setActiveProfile(id)
    const next = profiles.find((p) => p.id === id)
    if (next) setProfile(next)
    setSettings((prev) => ({ ...prev, activeProfileId: id }))
  }

  async function handleCreateProfile() {
    const name = prompt('New profile name?', `Profile ${profiles.length + 1}`)
    if (!name) return
    const base = profile
      ? { ...profile.config }
      : { ...DEFAULT_DRILL_CONFIG }
    const fresh = { ...buildDefaultProfile(base), name }
    await saveProfile(fresh)
    await setActiveProfile(fresh.id)
    setProfile(fresh)
    setProfiles((prev) => [...prev, fresh])
    setSettings((prev) => ({ ...prev, activeProfileId: fresh.id }))
  }

  async function handleRenameProfile() {
    if (!profile) return
    const name = prompt('Rename profile to:', profile.name)
    if (!name) return
    const renamed = { ...profile, name }
    await saveProfile(renamed)
    setProfile(renamed)
    setProfiles((prev) => prev.map((p) => (p.id === renamed.id ? renamed : p)))
  }

  async function handleDeleteProfile() {
    if (!profile) return
    if (profiles.length <= 1) {
      setErrors(['Cannot delete the only remaining profile.'])
      return
    }
    if (!confirm(`Delete profile "${profile.name}"?`)) return
    const remaining = profiles.filter((p) => p.id !== profile.id)
    await deleteProfile(profile.id)
    await setActiveProfile(remaining[0].id)
    setProfile(remaining[0])
    setProfiles(remaining)
    setSettings((prev) => ({ ...prev, activeProfileId: remaining[0].id }))
  }

  if (!loaded || !profile) {
    return (
      <div className="screen settings">
        <p>Loading settings…</p>
      </div>
    )
  }

  const config = profile.config
  const allowedCueIds = config.allowedCueIds ?? CUE_LIBRARY.map((c) => c.id)
  const allowedSet = new Set(allowedCueIds)

  return (
    <div className="screen settings">
      <header className="settings-header">
        <h1>Settings</h1>
        <button type="button" className="link" onClick={onClose}>
          Cancel
        </button>
      </header>

      <section className="settings-section">
        <h2>Profile</h2>
        <label>
          <span>Active profile</span>
          <select
            value={profile.id}
            onChange={(e) => void handleSwitchProfile(e.target.value)}
            aria-label="active profile"
          >
            {profiles.map((p) => (
              <option key={p.id} value={p.id}>
                {p.name}
              </option>
            ))}
          </select>
        </label>
        <div className="profile-actions">
          <button
            type="button"
            className="link"
            onClick={() => void handleCreateProfile()}
          >
            New profile
          </button>
          <button
            type="button"
            className="link"
            onClick={() => void handleRenameProfile()}
          >
            Rename
          </button>
          <button
            type="button"
            className="link"
            onClick={() => void handleDeleteProfile()}
          >
            Delete
          </button>
        </div>
      </section>

      <section className="settings-section">
        <h2>Input</h2>
        <label>
          <span>Input source</span>
          <select
            value={settings.inputSource}
            onChange={(e) =>
              updateSettings('inputSource', e.target.value as InputSource)
            }
          >
            <option value="keyboard">Keyboard (fallback / dev)</option>
            <option value="pedal">Foot pedal</option>
          </select>
        </label>
        <label>
          <span>Commit key</span>
          {rebinding ? (
            <span className="rebind-prompt">Press a key… (Esc to cancel)</span>
          ) : (
            <button
              type="button"
              className="rebind-button"
              onClick={() => setRebinding(true)}
              aria-label="Rebind commit key"
            >
              {settings.commitKeyLabel} ({settings.commitKeyCode})
            </button>
          )}
        </label>
        <p className="hint">
          USB foot pedals enumerate as keyboards. Configure your pedal to emit
          whichever key you bind here.
        </p>
      </section>

      <section className="settings-section">
        <h2>Rounds</h2>
        <label>
          <span>Round count</span>
          <input
            type="number"
            min={1}
            max={20}
            value={config.rounds}
            onChange={(e) =>
              updateConfig('rounds', Math.max(1, Number(e.target.value) || 1))
            }
          />
        </label>
        <label>
          <span>Work duration (seconds)</span>
          <input
            type="number"
            min={1}
            max={600}
            value={Math.round(config.workMs / 1000)}
            onChange={(e) =>
              updateConfig(
                'workMs',
                Math.max(1, Number(e.target.value) || 1) * 1000,
              )
            }
          />
        </label>
        <label>
          <span>Rest duration (seconds)</span>
          <input
            type="number"
            min={0}
            max={600}
            value={Math.round(config.restMs / 1000)}
            onChange={(e) =>
              updateConfig(
                'restMs',
                Math.max(0, Number(e.target.value) || 0) * 1000,
              )
            }
          />
        </label>
      </section>

      <section className="settings-section">
        <h2>Pre-cue delay</h2>
        <label>
          <span>Min (ms)</span>
          <input
            type="number"
            min={PRE_CUE_MIN_FLOOR_MS}
            max={PRE_CUE_MAX_CEILING_MS}
            step={100}
            value={config.preCueMinMs}
            onChange={(e) =>
              updateConfig('preCueMinMs', Number(e.target.value) || 0)
            }
          />
        </label>
        <label>
          <span>Max (ms)</span>
          <input
            type="number"
            min={PRE_CUE_MIN_FLOOR_MS}
            max={PRE_CUE_MAX_CEILING_MS}
            step={100}
            value={config.preCueMaxMs}
            onChange={(e) =>
              updateConfig('preCueMaxMs', Number(e.target.value) || 0)
            }
          />
        </label>
        <p className="hint">
          Range {PRE_CUE_MIN_FLOOR_MS}–{PRE_CUE_MAX_CEILING_MS} ms.
        </p>
      </section>

      <section className="settings-section">
        <h2>Choice-RT thresholds</h2>
        <label>
          <span>Hesitation threshold (ms)</span>
          <input
            type="number"
            min={100}
            max={2000}
            step={50}
            value={config.hesitationThresholdMs}
            onChange={(e) =>
              updateConfig(
                'hesitationThresholdMs',
                Number(e.target.value) || 0,
              )
            }
          />
        </label>
        <label>
          <span>Late threshold (ms)</span>
          <input
            type="number"
            min={100}
            max={3000}
            step={50}
            value={config.lateThresholdMs}
            onChange={(e) =>
              updateConfig('lateThresholdMs', Number(e.target.value) || 0)
            }
          />
        </label>
        <label>
          <span>Response window (ms)</span>
          <input
            type="number"
            min={100}
            max={5000}
            step={50}
            value={config.responseWindowMs}
            onChange={(e) =>
              updateConfig('responseWindowMs', Number(e.target.value) || 0)
            }
          />
        </label>
        <p className="hint">
          hesitation &lt; late &lt; response-window. Defaults 450 / 600 / 1200.
        </p>
      </section>

      <section className="settings-section">
        <h2>Cue subset</h2>
        <div className="cue-subset-grid">
          {CUE_LIBRARY.map((cue) => (
            <label key={cue.id} className="checkbox-row">
              <input
                type="checkbox"
                checked={allowedSet.has(cue.id)}
                onChange={() => toggleAllowedCue(cue.id)}
              />
              <span>{cue.label}</span>
            </label>
          ))}
        </div>
        <p className="hint">
          Uncheck to remove a cue from this profile. Must keep at least one go
          cue.
        </p>
      </section>

      <section className="settings-section">
        <h2>Scoring weights</h2>
        <div className="score-grid">
          {SCORE_FIELDS.map((f) => (
            <label key={f.key}>
              <span>{f.label}</span>
              <input
                type="number"
                step={1}
                value={config.scoreWeights[f.key]}
                onChange={(e) =>
                  updateScoreWeight(f.key, Number(e.target.value) || 0)
                }
              />
            </label>
          ))}
        </div>
      </section>

      <section className="settings-section">
        <h2>Visuals</h2>
        <label className="checkbox-row">
          <input
            type="checkbox"
            checked={config.distanceAxisEnabled}
            onChange={(e) =>
              updateConfig('distanceAxisEnabled', e.target.checked)
            }
          />
          <span>
            Enable distance axis (far / mid / in-range changes correct
            response)
          </span>
        </label>
        <label className="checkbox-row">
          <input
            type="checkbox"
            checked={config.audioToneEnabled}
            onChange={(e) => updateConfig('audioToneEnabled', e.target.checked)}
          />
          <span>Audio tone tracks distance (low → high pitch)</span>
        </label>
        <label className="checkbox-row">
          <input
            type="checkbox"
            checked={config.textOverlayEnabled}
            onChange={(e) =>
              updateConfig('textOverlayEnabled', e.target.checked)
            }
          />
          <span>Show text label overlay (learning mode)</span>
        </label>
      </section>

      <section className="settings-section">
        <h2>Penalty counter</h2>
        <label className="checkbox-row">
          <input
            type="checkbox"
            checked={config.penaltyCounterEnabled}
            onChange={(e) =>
              updateConfig('penaltyCounterEnabled', e.target.checked)
            }
          />
          <span>
            False starts and hesitations add reps to a during-rest clear-list
          </span>
        </label>
        {config.penaltyCounterEnabled && (
          <>
            <label>
              <span>Reps per false start</span>
              <input
                type="number"
                min={0}
                max={20}
                value={config.perFalseStartPenalty}
                onChange={(e) =>
                  updateConfig(
                    'perFalseStartPenalty',
                    Math.max(0, Number(e.target.value) || 0),
                  )
                }
              />
            </label>
            <label>
              <span>Reps per hesitation</span>
              <input
                type="number"
                min={0}
                max={20}
                value={config.perHesitationPenalty}
                onChange={(e) =>
                  updateConfig(
                    'perHesitationPenalty',
                    Math.max(0, Number(e.target.value) || 0),
                  )
                }
              />
            </label>
          </>
        )}
      </section>

      {errors.length > 0 && (
        <div className="banner warn">
          <ul>
            {errors.map((e) => (
              <li key={e}>{e}</li>
            ))}
          </ul>
        </div>
      )}

      <div className="actions">
        <button type="button" className="primary" onClick={() => void handleSave()}>
          Save
        </button>
      </div>
    </div>
  )
}

function humanizeKeyCode(code: string, key: string): string {
  if (code === 'Space') return 'Space'
  if (code.startsWith('Key')) return code.slice(3)
  if (code.startsWith('Digit')) return code.slice(5)
  if (code === 'Enter') return 'Enter'
  return key.length === 1 ? key.toUpperCase() : code
}

