import { CUE_LIBRARY } from '../cues/library'
import type {
  CueId,
  DrillConfig,
  RepRecord,
  RepResult,
  SessionRecord,
} from './types'
import { DEFAULT_DRILL_CONFIG } from './types'
import { best10AvgOf } from './drill'

const CUE_IS_GO: Record<CueId, boolean> = (() => {
  const m = {} as Record<CueId, boolean>
  for (const c of CUE_LIBRARY) m[c.id] = c.isGo
  return m
})()

export interface SessionTrendPoint {
  sessionId: string
  startedAt: number
  reps: number
  falseStartRate: number
  hesitationRate: number
  lateRate: number
  avgRtMs: number | null
  best10AvgRtMs: number | null
  score: number
}

export interface CueTrendPoint {
  sessionId: string
  startedAt: number
  cueId: CueId
  reps: number
  avgRtMs: number | null
  errorRate: number
}

export interface CueAggregateRow {
  cueId: CueId
  isGo: boolean
  reps: number
  sessions: number
  avgRtMs: number | null
  best10AvgRtMs: number | null
  errorRate: number
  goWeakness: number | null
  noGoWeakness: number | null
}

export type CueCompareClassification =
  | 'both_measured'
  | 'both_error_only'
  | 'candidate_only'
  | 'baseline_only'

export interface CueCompareRow {
  cueId: CueId
  classification: CueCompareClassification
  deltaAvgRtMs: number | null
  deltaErrorRate: number
}

export interface SessionDelta {
  baselineId: string
  candidateId: string
  deltaAvgRtMs: number | null
  deltaScore: number | null
  deltaFalseStartRate: number
  deltaHesitationRate: number
  weightsDiffer: boolean
  perCue: CueCompareRow[]
}

export interface TaperRecommendation {
  cueIds: CueId[]
  reason: string
}

// ---------------------------------------------------------------------------
// Per-session aggregators (small private helpers reused across exports)

function correctGoTimes(reps: RepRecord[]): number[] {
  return reps
    .filter((r) => r.result === 'correct_go' && r.reactionMs !== null)
    .map((r) => r.reactionMs as number)
}

function trendPointFromReps(
  sessionId: string,
  startedAt: number,
  reps: RepRecord[],
): SessionTrendPoint {
  const total = reps.length
  const goTimes = correctGoTimes(reps)
  const avg =
    goTimes.length === 0
      ? null
      : Math.round(goTimes.reduce((a, b) => a + b, 0) / goTimes.length)
  return {
    sessionId,
    startedAt,
    reps: total,
    falseStartRate:
      total === 0 ? 0 : reps.filter((r) => r.result === 'false_start').length / total,
    hesitationRate:
      total === 0 ? 0 : reps.filter((r) => r.result === 'hesitation').length / total,
    lateRate:
      total === 0 ? 0 : reps.filter((r) => r.result === 'late').length / total,
    avgRtMs: avg,
    best10AvgRtMs: best10AvgOf(goTimes),
    score: reps.reduce((a, r) => a + r.score, 0),
  }
}

// ---------------------------------------------------------------------------
// Public API

export function sessionTrend(
  sessions: readonly SessionRecord[],
  repsBySession: Map<string, RepRecord[]>,
): SessionTrendPoint[] {
  return sessions
    .filter((s) => (repsBySession.get(s.id) ?? []).length > 0)
    .map((s) =>
      trendPointFromReps(s.id, s.startedAt, repsBySession.get(s.id) ?? []),
    )
    .sort((a, b) => a.startedAt - b.startedAt)
}

export function cueTrend(
  sessions: readonly SessionRecord[],
  repsBySession: Map<string, RepRecord[]>,
): CueTrendPoint[] {
  const out: CueTrendPoint[] = []
  const ordered = [...sessions].sort((a, b) => a.startedAt - b.startedAt)
  for (const s of ordered) {
    const reps = repsBySession.get(s.id) ?? []
    if (reps.length === 0) continue
    const byCue = new Map<CueId, RepRecord[]>()
    for (const r of reps) {
      const list = byCue.get(r.cueId) ?? []
      list.push(r)
      byCue.set(r.cueId, list)
    }
    for (const [cueId, list] of byCue) {
      const goTimes = correctGoTimes(list)
      const avg =
        goTimes.length === 0
          ? null
          : Math.round(goTimes.reduce((a, b) => a + b, 0) / goTimes.length)
      const correct = list.filter(
        (r) => r.result === 'correct_go' || r.result === 'correct_no_go',
      ).length
      out.push({
        sessionId: s.id,
        startedAt: s.startedAt,
        cueId,
        reps: list.length,
        avgRtMs: avg,
        errorRate: list.length === 0 ? 0 : (list.length - correct) / list.length,
      })
    }
  }
  return out
}

export function cueAggregate(
  sessions: readonly SessionRecord[],
  repsBySession: Map<string, RepRecord[]>,
): CueAggregateRow[] {
  const byCue = new Map<CueId, RepRecord[]>()
  const sessionsPerCue = new Map<CueId, Set<string>>()
  for (const s of sessions) {
    const reps = repsBySession.get(s.id) ?? []
    for (const r of reps) {
      const list = byCue.get(r.cueId) ?? []
      list.push(r)
      byCue.set(r.cueId, list)
      const sset = sessionsPerCue.get(r.cueId) ?? new Set<string>()
      sset.add(s.id)
      sessionsPerCue.set(r.cueId, sset)
    }
  }
  const rows: CueAggregateRow[] = []
  for (const [cueId, list] of byCue) {
    const isGo = CUE_IS_GO[cueId] ?? true
    const goTimes = correctGoTimes(list)
    const avg =
      goTimes.length === 0
        ? null
        : Math.round(goTimes.reduce((a, b) => a + b, 0) / goTimes.length)
    const correct = list.filter(
      (r) => r.result === 'correct_go' || r.result === 'correct_no_go',
    ).length
    const errorRate =
      list.length === 0 ? 0 : (list.length - correct) / list.length
    const goWeakness =
      isGo && avg !== null ? avg / 1000 + errorRate : null
    const noGoWeakness = !isGo ? errorRate : null
    rows.push({
      cueId,
      isGo,
      reps: list.length,
      sessions: sessionsPerCue.get(cueId)?.size ?? 0,
      avgRtMs: avg,
      best10AvgRtMs: best10AvgOf(goTimes),
      errorRate,
      goWeakness,
      noGoWeakness,
    })
  }
  return rows
}

// ---------------------------------------------------------------------------
// Taper picker — see decision-memo D5 for the go/no-go split rationale.

const MIN_REPS_PER_CUE = 5
const MIN_SESSIONS_PER_CUE = 2

function eligible(row: CueAggregateRow): boolean {
  return row.reps >= MIN_REPS_PER_CUE && row.sessions >= MIN_SESSIONS_PER_CUE
}

function byWeaknessDesc<K extends 'goWeakness' | 'noGoWeakness'>(
  field: K,
): (a: CueAggregateRow, b: CueAggregateRow) => number {
  return (a, b) => {
    const av = a[field] ?? -Infinity
    const bv = b[field] ?? -Infinity
    if (bv !== av) return bv - av
    return a.cueId < b.cueId ? -1 : a.cueId > b.cueId ? 1 : 0
  }
}

export function pickTaperCues(
  aggregate: readonly CueAggregateRow[],
  k: number,
): TaperRecommendation {
  if (k <= 0) return { cueIds: [], reason: 'k must be ≥ 1' }
  const eligibleRows = aggregate.filter(eligible)
  if (eligibleRows.length === 0) {
    return {
      cueIds: [],
      reason:
        'Not enough data — every cue has fewer than 5 reps across at least 2 sessions. Drill more variety first.',
    }
  }
  const goSlots = Math.max(1, Math.floor(k * 0.7))
  const noGoSlots = k - goSlots
  const goPool = eligibleRows
    .filter((r) => r.isGo && r.goWeakness !== null)
    .sort(byWeaknessDesc('goWeakness'))
  const noGoPool = eligibleRows
    .filter((r) => !r.isGo && r.noGoWeakness !== null)
    .sort(byWeaknessDesc('noGoWeakness'))

  // Take initial slots from each pool, then fill any deficit from the other.
  const goPicks = goPool.slice(0, goSlots)
  const noGoPicks = noGoPool.slice(0, noGoSlots)
  const goShort = goSlots - goPicks.length
  const noGoShort = noGoSlots - noGoPicks.length
  const filledFromNoGo = noGoPool
    .slice(noGoPicks.length, noGoPicks.length + goShort)
  const filledFromGo = goPool.slice(goPicks.length, goPicks.length + noGoShort)
  const all = [...goPicks, ...filledFromNoGo, ...noGoPicks, ...filledFromGo]
  const cueIds = all.map((r) => r.cueId)

  const goNames = goPicks.map((r) => r.cueId).join(', ')
  const noGoNames = noGoPicks.map((r) => r.cueId).join(', ')
  const parts: string[] = []
  if (goNames) parts.push(`slowest go cues: ${goNames}`)
  if (noGoNames) parts.push(`weakest no-go cues: ${noGoNames}`)
  if (filledFromNoGo.length > 0)
    parts.push(`extra no-go: ${filledFromNoGo.map((r) => r.cueId).join(', ')}`)
  if (filledFromGo.length > 0)
    parts.push(`extra go: ${filledFromGo.map((r) => r.cueId).join(', ')}`)
  const reason =
    cueIds.length === 0
      ? 'Not enough eligible cues. Drill more variety first.'
      : parts.join(' · ')
  return { cueIds, reason }
}

// ---------------------------------------------------------------------------
// Session comparison

function scoreByResultOf(reps: RepRecord[]): Map<RepResult, number> {
  const m = new Map<RepResult, number>()
  for (const r of reps) {
    if (!m.has(r.result)) m.set(r.result, r.score)
  }
  return m
}

function weightsDifferBetween(
  a: Map<RepResult, number>,
  b: Map<RepResult, number>,
): boolean {
  for (const [k, va] of a) {
    const vb = b.get(k)
    if (vb !== undefined && vb !== va) return true
  }
  return false
}

function cuePerf(
  reps: RepRecord[],
  cueId: CueId,
): { count: number; correct: number; avgRtMs: number | null; errorRate: number } {
  const list = reps.filter((r) => r.cueId === cueId)
  if (list.length === 0) {
    return { count: 0, correct: 0, avgRtMs: null, errorRate: 0 }
  }
  const correct = list.filter(
    (r) => r.result === 'correct_go' || r.result === 'correct_no_go',
  ).length
  const goTimes = correctGoTimes(list)
  const avg =
    goTimes.length === 0
      ? null
      : Math.round(goTimes.reduce((a, b) => a + b, 0) / goTimes.length)
  return {
    count: list.length,
    correct,
    avgRtMs: avg,
    errorRate: (list.length - correct) / list.length,
  }
}

export function compareSessions(
  baseline: SessionRecord,
  candidate: SessionRecord,
  baselineReps: RepRecord[],
  candidateReps: RepRecord[],
): SessionDelta {
  const baseTrend = trendPointFromReps(
    baseline.id,
    baseline.startedAt,
    baselineReps,
  )
  const candTrend = trendPointFromReps(
    candidate.id,
    candidate.startedAt,
    candidateReps,
  )
  const weightsDiffer = weightsDifferBetween(
    scoreByResultOf(baselineReps),
    scoreByResultOf(candidateReps),
  )
  const cueIds = new Set<CueId>()
  for (const r of baselineReps) cueIds.add(r.cueId)
  for (const r of candidateReps) cueIds.add(r.cueId)
  const perCue: CueCompareRow[] = []
  for (const cueId of cueIds) {
    const a = cuePerf(baselineReps, cueId)
    const b = cuePerf(candidateReps, cueId)
    if (a.count === 0 && b.count > 0) {
      perCue.push({
        cueId,
        classification: 'candidate_only',
        deltaAvgRtMs: null,
        deltaErrorRate: 0,
      })
      continue
    }
    if (b.count === 0 && a.count > 0) {
      perCue.push({
        cueId,
        classification: 'baseline_only',
        deltaAvgRtMs: null,
        deltaErrorRate: 0,
      })
      continue
    }
    if (a.avgRtMs === null || b.avgRtMs === null) {
      // Both sides have reps but at least one has zero correct_go RTs.
      perCue.push({
        cueId,
        classification: 'both_error_only',
        deltaAvgRtMs: null,
        deltaErrorRate: b.errorRate - a.errorRate,
      })
      continue
    }
    perCue.push({
      cueId,
      classification: 'both_measured',
      deltaAvgRtMs: b.avgRtMs - a.avgRtMs,
      deltaErrorRate: b.errorRate - a.errorRate,
    })
  }
  perCue.sort((x, y) => (x.cueId < y.cueId ? -1 : x.cueId > y.cueId ? 1 : 0))

  const deltaAvgRtMs =
    baseTrend.avgRtMs === null || candTrend.avgRtMs === null
      ? null
      : candTrend.avgRtMs - baseTrend.avgRtMs

  return {
    baselineId: baseline.id,
    candidateId: candidate.id,
    deltaAvgRtMs,
    deltaScore: weightsDiffer ? null : candTrend.score - baseTrend.score,
    deltaFalseStartRate: candTrend.falseStartRate - baseTrend.falseStartRate,
    deltaHesitationRate: candTrend.hesitationRate - baseTrend.hesitationRate,
    weightsDiffer,
    perCue,
  }
}

import { useEffect, useState } from 'react'
import {
  DEFAULT_SETTINGS,
  loadActiveProfile,
  loadSettings,
  saveSettings,
  setActiveProfile,
  type SettingsRecord,
} from '../store/settings'
import {
  buildDefaultProfile,
  deleteProfile,
  listProfiles,
  saveProfile,
  type ProfileRecord,
} from '../store/profiles'
import { validateDrillConfig } from '../engine/drill'
import { cueAggregate, pickTaperCues } from '../engine/analytics'
import { listRecentSessions, listRepsForSessions } from '../store/db'
import { CUE_LIBRARY } from '../cues/library'
import {
  DEFAULT_DRILL_CONFIG,
  PRE_CUE_MAX_CEILING_MS,
  PRE_CUE_MIN_FLOOR_MS,
  type CueId,
  type DrillConfig,
  type InputSource,
  type RepResult,
} from '../engine/types'

interface SettingsScreenProps {
  onClose: () => void
}

const SCORE_FIELDS: { key: RepResult; label: string }[] = [
  { key: 'correct_go', label: 'Correct go' },
  { key: 'correct_no_go', label: 'Correct no-go' },
  { key: 'late', label: 'Late' },
  { key: 'hesitation', label: 'Hesitation' },
  { key: 'false_start', label: 'False start' },
]

export function SettingsScreen({ onClose }: SettingsScreenProps) {
  const [settings, setSettings] = useState<SettingsRecord>(DEFAULT_SETTINGS)
  const [profile, setProfile] = useState<ProfileRecord | null>(null)
  const [profiles, setProfiles] = useState<ProfileRecord[]>([])
  const [loaded, setLoaded] = useState(false)
  const [rebinding, setRebinding] = useState(false)
  const [errors, setErrors] = useState<string[]>([])
  const [taperReason, setTaperReason] = useState<string | null>(null)
  const [taperError, setTaperError] = useState<string | null>(null)

  useEffect(() => {
    let cancelled = false
    void Promise.all([loadSettings(), loadActiveProfile(), listProfiles()]).then(
      ([s, p, all]) => {
        if (cancelled) return
        setSettings(s)
        setProfile(p)
        setProfiles(all)
        setLoaded(true)
      },
    )
    return () => {
      cancelled = true
    }
  }, [])

  useEffect(() => {
    if (!rebinding) return
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        setRebinding(false)
        return
      }
      e.preventDefault()
      setSettings((prev) => ({
        ...prev,
        commitKeyCode: e.code,
        commitKeyLabel: humanizeKeyCode(e.code, e.key),
      }))
      setRebinding(false)
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [rebinding])

  function updateSettings<K extends keyof SettingsRecord>(
    key: K,
    value: SettingsRecord[K],
  ): void {
    setSettings((prev) => ({ ...prev, [key]: value }))
  }

  function updateConfig<K extends keyof DrillConfig>(
    key: K,
    value: DrillConfig[K],
  ): void {
    setProfile((prev) =>
      prev ? { ...prev, config: { ...prev.config, [key]: value } } : prev,
    )
  }

  function updateScoreWeight(result: RepResult, value: number): void {
    setProfile((prev) =>
      prev
        ? {
            ...prev,
            config: {
              ...prev.config,
              scoreWeights: { ...prev.config.scoreWeights, [result]: value },
            },
          }
        : prev,
    )
  }

  function toggleAllowedCue(cueId: CueId): void {
    setProfile((prev) => {
      if (!prev) return prev
      const current = prev.config.allowedCueIds ?? CUE_LIBRARY.map((c) => c.id)
      const set = new Set(current)
      if (set.has(cueId)) set.delete(cueId)
      else set.add(cueId)
      const next =
        set.size === CUE_LIBRARY.length ? null : Array.from(set)
      return { ...prev, config: { ...prev.config, allowedCueIds: next } }
    })
  }

  async function handleSave() {
    if (!profile) return
    const errs = validateDrillConfig(profile.config)
    if (errs.length > 0) {
      setErrors(errs.map((e) => `${e.field}: ${e.message}`))
      return
    }
    setErrors([])
    await saveProfile(profile)
    await saveSettings(settings)
    onClose()
  }

  async function handleSwitchProfile(id: string) {
    if (!id || id === profile?.id) return
    await setActiveProfile(id)
    const next = profiles.find((p) => p.id === id)
    if (next) setProfile(next)
    setSettings((prev) => ({ ...prev, activeProfileId: id }))
  }

  async function handleCreateProfile() {
    const name = prompt('New profile name?', `Profile ${profiles.length + 1}`)
    if (!name) return
    const base = profile
      ? { ...profile.config }
      : { ...DEFAULT_DRILL_CONFIG }
    const fresh = { ...buildDefaultProfile(base), name }
    await saveProfile(fresh)
    await setActiveProfile(fresh.id)
    setProfile(fresh)
    setProfiles((prev) => [...prev, fresh])
    setSettings((prev) => ({ ...prev, activeProfileId: fresh.id }))
  }

  async function handleRenameProfile() {
    if (!profile) return
    const name = prompt('Rename profile to:', profile.name)
    if (!name) return
    const renamed = { ...profile, name }
    await saveProfile(renamed)
    setProfile(renamed)
    setProfiles((prev) => prev.map((p) => (p.id === renamed.id ? renamed : p)))
  }

  async function handleDeleteProfile() {
    if (!profile) return
    if (profiles.length <= 1) {
      setErrors(['Cannot delete the only remaining profile.'])
      return
    }
    if (!confirm(`Delete profile "${profile.name}"?`)) return
    const remaining = profiles.filter((p) => p.id !== profile.id)
    await deleteProfile(profile.id)
    await setActiveProfile(remaining[0].id)
    setProfile(remaining[0])
    setProfiles(remaining)
    setSettings((prev) => ({ ...prev, activeProfileId: remaining[0].id }))
  }

  async function handleBuildTaperProfile() {
    const sessions = await listRecentSessions(5)
    if (sessions.length === 0) {
      setTaperError('No sessions yet — run a drill first.')
      return
    }
    const reps = await listRepsForSessions(sessions.map((s) => s.id))
    const agg = cueAggregate(sessions, reps)
    const rec = pickTaperCues(agg, 3)
    if (rec.cueIds.length === 0) {
      setTaperError(rec.reason)
      return
    }
    const today = new Date().toISOString().slice(0, 10)
    const name = `Taper — ${today}`
    const config: DrillConfig = {
      ...DEFAULT_DRILL_CONFIG,
      ...profile?.config,
      rounds: 3,
      workMs: 60_000,
      restMs: 30_000,
      maxReps: null,
      allowedCueIds: rec.cueIds,
    }
    const fresh = { ...buildDefaultProfile(config), name }
    await saveProfile(fresh)
    await setActiveProfile(fresh.id)
    setProfile(fresh)
    setProfiles((prev) => [...prev, fresh])
    setSettings((prev) => ({ ...prev, activeProfileId: fresh.id }))
    setTaperReason(rec.reason)
    setTaperError(null)
  }

  if (!loaded || !profile) {
    return (
      <div className="screen settings">
        <p>Loading settings…</p>
      </div>
    )
  }

  const config = profile.config
  const allowedCueIds = config.allowedCueIds ?? CUE_LIBRARY.map((c) => c.id)
  const allowedSet = new Set(allowedCueIds)

  return (
    <div className="screen settings">
      <header className="settings-header">
        <h1>Settings</h1>
        <button type="button" className="link" onClick={onClose}>
          Cancel
        </button>
      </header>

      <section className="settings-section">
        <h2>Profile</h2>
        <label>
          <span>Active profile</span>
          <select
            value={profile.id}
            onChange={(e) => void handleSwitchProfile(e.target.value)}
            aria-label="active profile"
          >
            {profiles.map((p) => (
              <option key={p.id} value={p.id}>
                {p.name}
              </option>
            ))}
          </select>
        </label>
        <div className="profile-actions">
          <button
            type="button"
            className="link"
            onClick={() => void handleCreateProfile()}
          >
            New profile
          </button>
          <button
            type="button"
            className="link"
            onClick={() => void handleRenameProfile()}
          >
            Rename
          </button>
          <button
            type="button"
            className="link"
            onClick={() => void handleDeleteProfile()}
          >
            Delete
          </button>
        </div>
      </section>

      <section className="settings-section">
        <h2>Input</h2>
        <label>
          <span>Input source</span>
          <select
            value={settings.inputSource}
            onChange={(e) =>
              updateSettings('inputSource', e.target.value as InputSource)
            }
          >
            <option value="keyboard">Keyboard (fallback / dev)</option>
            <option value="pedal">Foot pedal</option>
          </select>
        </label>
        <label>
          <span>Commit key</span>
          {rebinding ? (
            <span className="rebind-prompt">Press a key… (Esc to cancel)</span>
          ) : (
            <button
              type="button"
              className="rebind-button"
              onClick={() => setRebinding(true)}
              aria-label="Rebind commit key"
            >
              {settings.commitKeyLabel} ({settings.commitKeyCode})
            </button>
          )}
        </label>
        <p className="hint">
          USB foot pedals enumerate as keyboards. Configure your pedal to emit
          whichever key you bind here.
        </p>
      </section>

      <section className="settings-section">
        <h2>Rounds</h2>
        <label>
          <span>Round count</span>
          <input
            type="number"
            min={1}
            max={20}
            value={config.rounds}
            onChange={(e) =>
              updateConfig('rounds', Math.max(1, Number(e.target.value) || 1))
            }
          />
        </label>
        <label>
          <span>Work duration (seconds)</span>
          <input
            type="number"
            min={1}
            max={600}
            value={Math.round(config.workMs / 1000)}
            onChange={(e) =>
              updateConfig(
                'workMs',
                Math.max(1, Number(e.target.value) || 1) * 1000,
              )
            }
          />
        </label>
        <label>
          <span>Rest duration (seconds)</span>
          <input
            type="number"
            min={0}
            max={600}
            value={Math.round(config.restMs / 1000)}
            onChange={(e) =>
              updateConfig(
                'restMs',
                Math.max(0, Number(e.target.value) || 0) * 1000,
              )
            }
          />
        </label>
      </section>

      <section className="settings-section">
        <h2>Pre-cue delay</h2>
        <label>
          <span>Min (ms)</span>
          <input
            type="number"
            min={PRE_CUE_MIN_FLOOR_MS}
            max={PRE_CUE_MAX_CEILING_MS}
            step={100}
            value={config.preCueMinMs}
            onChange={(e) =>
              updateConfig('preCueMinMs', Number(e.target.value) || 0)
            }
          />
        </label>
        <label>
          <span>Max (ms)</span>
          <input
            type="number"
            min={PRE_CUE_MIN_FLOOR_MS}
            max={PRE_CUE_MAX_CEILING_MS}
            step={100}
            value={config.preCueMaxMs}
            onChange={(e) =>
              updateConfig('preCueMaxMs', Number(e.target.value) || 0)
            }
          />
        </label>
        <p className="hint">
          Range {PRE_CUE_MIN_FLOOR_MS}–{PRE_CUE_MAX_CEILING_MS} ms.
        </p>
      </section>

      <section className="settings-section">
        <h2>Choice-RT thresholds</h2>
        <label>
          <span>Hesitation threshold (ms)</span>
          <input
            type="number"
            min={100}
            max={2000}
            step={50}
            value={config.hesitationThresholdMs}
            onChange={(e) =>
              updateConfig(
                'hesitationThresholdMs',
                Number(e.target.value) || 0,
              )
            }
          />
        </label>
        <label>
          <span>Late threshold (ms)</span>
          <input
            type="number"
            min={100}
            max={3000}
            step={50}
            value={config.lateThresholdMs}
            onChange={(e) =>
              updateConfig('lateThresholdMs', Number(e.target.value) || 0)
            }
          />
        </label>
        <label>
          <span>Response window (ms)</span>
          <input
            type="number"
            min={100}
            max={5000}
            step={50}
            value={config.responseWindowMs}
            onChange={(e) =>
              updateConfig('responseWindowMs', Number(e.target.value) || 0)
            }
          />
        </label>
        <p className="hint">
          hesitation &lt; late &lt; response-window. Defaults 450 / 600 / 1200.
        </p>
      </section>

      <section className="settings-section">
        <h2>Cue subset</h2>
        <div className="cue-subset-grid">
          {CUE_LIBRARY.map((cue) => (
            <label key={cue.id} className="checkbox-row">
              <input
                type="checkbox"
                checked={allowedSet.has(cue.id)}
                onChange={() => toggleAllowedCue(cue.id)}
              />
              <span>{cue.label}</span>
            </label>
          ))}
        </div>
        <p className="hint">
          Uncheck to remove a cue from this profile. Must keep at least one go
          cue.
        </p>
      </section>

      <section className="settings-section">
        <h2>Scoring weights</h2>
        <div className="score-grid">
          {SCORE_FIELDS.map((f) => (
            <label key={f.key}>
              <span>{f.label}</span>
              <input
                type="number"
                step={1}
                value={config.scoreWeights[f.key]}
                onChange={(e) =>
                  updateScoreWeight(f.key, Number(e.target.value) || 0)
                }
              />
            </label>
          ))}
        </div>
      </section>

      <section className="settings-section">
        <h2>Visuals</h2>
        <label className="checkbox-row">
          <input
            type="checkbox"
            checked={config.distanceAxisEnabled}
            onChange={(e) =>
              updateConfig('distanceAxisEnabled', e.target.checked)
            }
          />
          <span>
            Enable distance axis (far / mid / in-range changes correct
            response)
          </span>
        </label>
        <label className="checkbox-row">
          <input
            type="checkbox"
            checked={config.audioToneEnabled}
            onChange={(e) => updateConfig('audioToneEnabled', e.target.checked)}
          />
          <span>Audio tone tracks distance (low → high pitch)</span>
        </label>
        <label className="checkbox-row">
          <input
            type="checkbox"
            checked={config.textOverlayEnabled}
            onChange={(e) =>
              updateConfig('textOverlayEnabled', e.target.checked)
            }
          />
          <span>Show text label overlay (learning mode)</span>
        </label>
      </section>

      <section className="settings-section">
        <h2>Penalty counter</h2>
        <label className="checkbox-row">
          <input
            type="checkbox"
            checked={config.penaltyCounterEnabled}
            onChange={(e) =>
              updateConfig('penaltyCounterEnabled', e.target.checked)
            }
          />
          <span>
            False starts and hesitations add reps to a during-rest clear-list
          </span>
        </label>
        {config.penaltyCounterEnabled && (
          <>
            <label>
              <span>Reps per false start</span>
              <input
                type="number"
                min={0}
                max={20}
                value={config.perFalseStartPenalty}
                onChange={(e) =>
                  updateConfig(
                    'perFalseStartPenalty',
                    Math.max(0, Number(e.target.value) || 0),
                  )
                }
              />
            </label>
            <label>
              <span>Reps per hesitation</span>
              <input
                type="number"
                min={0}
                max={20}
                value={config.perHesitationPenalty}
                onChange={(e) =>
                  updateConfig(
                    'perHesitationPenalty',
                    Math.max(0, Number(e.target.value) || 0),
                  )
                }
              />
            </label>
          </>
        )}
      </section>

      <section className="settings-section">
        <h2>Taper mode</h2>
        <p className="hint">
          Auto-build a low-volume profile (3 × 60s work / 30s rest) using only
          the cues you were slowest or least accurate on in the last 5
          sessions.
        </p>
        <div className="profile-actions">
          <button
            type="button"
            className="link"
            onClick={() => void handleBuildTaperProfile()}
          >
            Build taper profile
          </button>
        </div>
        {taperReason && (
          <div className="banner info" role="status">
            Taper profile created. {taperReason}
          </div>
        )}
        {taperError && <div className="banner warn">{taperError}</div>}
      </section>

      {errors.length > 0 && (
        <div className="banner warn">
          <ul>
            {errors.map((e) => (
              <li key={e}>{e}</li>
            ))}
          </ul>
        </div>
      )}

      <div className="actions">
        <button type="button" className="primary" onClick={() => void handleSave()}>
          Save
        </button>
      </div>
    </div>
  )
}

function humanizeKeyCode(code: string, key: string): string {
  if (code === 'Space') return 'Space'
  if (code.startsWith('Key')) return code.slice(3)
  if (code.startsWith('Digit')) return code.slice(5)
  if (code === 'Enter') return 'Enter'
  return key.length === 1 ? key.toUpperCase() : code
}

