289	export function antiRhythmSignal(reps: RepRecord[]): AntiRhythmStats {
290	  const buckets: AntiRhythmStats['buckets'] = {
291	    '0': { falseStarts: 0, total: 0 },
292	    '1': { falseStarts: 0, total: 0 },
293	    '2': { falseStarts: 0, total: 0 },
294	    '3+': { falseStarts: 0, total: 0 },
295	  }
296	  let streak = 0
297	  let totalGoReps = 0
298	  let totalFalseStarts = 0
299	  for (const r of reps) {
300	    if (r.isGo) {
301	      const b = priorGoStreakBucketOf(streak)
302	      buckets[b].total += 1
303	      if (r.result === 'false_start') buckets[b].falseStarts += 1
304	      totalGoReps += 1
305	      if (r.result === 'false_start') totalFalseStarts += 1
306	      streak += 1
307	    } else {
308	      streak = 0
309	    }
310	  }
311	  const overallFalseStartRate =
312	    totalGoReps === 0 ? 0 : totalFalseStarts / totalGoReps
313	
314	  let narrative = 'No rhythm pattern detected.'
315	  let bestBucket: PriorGoStreakBucket | null = null
316	  let bestRate = -1
317	  for (const key of Object.keys(buckets) as PriorGoStreakBucket[]) {
318	    const b = buckets[key]
319	    if (b.total < 3) continue
320	    const rate = b.falseStarts / b.total
321	    if (
322	      rate > bestRate &&
323	      overallFalseStartRate > 0 &&
324	      rate >= overallFalseStartRate * 1.5
325	    ) {
326	      bestRate = rate
327	      bestBucket = key
328	    }
329	  }
330	  if (bestBucket !== null) {
331	    const pct = Math.round(bestRate * 100)
332	    const label =
333	      bestBucket === '0'
334	        ? 'a non-go cue'
335	        : bestBucket === '3+'
336	          ? '3+ consecutive go cues'
337	          : `${bestBucket} consecutive go cue${bestBucket === '1' ? '' : 's'}`
338	    narrative = `False starts most often after ${label} (${pct}%).`
339	  }
340	
341	  return { overallFalseStartRate, buckets, narrative }
342	}
343	
344	export function summarize(reps: RepRecord[]): SessionSummary {
345	  const reactionTimes = reps
346	    .filter((r) => r.result === 'correct_go' && r.reactionMs !== null)
347	    .map((r) => r.reactionMs as number)
348	
349	  const avgReactionMs =
350	    reactionTimes.length === 0
351	      ? null
352	      : Math.round(
353	          reactionTimes.reduce((a, b) => a + b, 0) / reactionTimes.length,
354	        )
355	
356	  return {
357	    reps: reps.length,
358	    correct: reps.filter(
359	      (r) => r.result === 'correct_go' || r.result === 'correct_no_go',
360	    ).length,
361	    falseStarts: reps.filter((r) => r.result === 'false_start').length,
362	    lateMisses: reps.filter((r) => r.result === 'late').length,
363	    hesitations: reps.filter((r) => r.result === 'hesitation').length,
364	    score: reps.reduce((a, r) => a + r.score, 0),
365	    avgReactionMs,
366	  }
367	}
