import { CUE_LIBRARY, GO_CUES, NO_GO_CUES } from '../cues/library'
import type {
  CueDef,
  CueDistanceEntry,
  Distance,
  DrillConfig,
  RepRecord,
  RepResult,
  SessionSummary,
} from './types'
import {
  DISTANCES,
  PRE_CUE_MAX_CEILING_MS,
  PRE_CUE_MIN_FLOOR_MS,
} from './types'
import { randInt, type RNG } from './rng'

export function pickPreCueDelayMs(rng: RNG, config: DrillConfig): number {
  return randInt(rng, config.preCueMinMs, config.preCueMaxMs)
}

function filterByAllowed(
  cues: readonly CueDef[],
  allowed: CueDef['id'][] | null,
): readonly CueDef[] {
  if (!allowed || allowed.length === 0) return cues
  const set = new Set(allowed)
  return cues.filter((c) => set.has(c.id))
}

export function pickNextCue(rng: RNG, config: DrillConfig): CueDef {
  if (config.distanceAxisEnabled) {
    const pool = filterByAllowed(CUE_LIBRARY, config.allowedCueIds)
    if (pool.length === 0) {
      throw new Error('pickNextCue: empty library after allowedCueIds filter')
    }
    return pool[Math.floor(rng() * pool.length)]
  }
  const allowedGo = filterByAllowed(GO_CUES, config.allowedCueIds)
  const allowedNoGo = filterByAllowed(NO_GO_CUES, config.allowedCueIds)
  const goEmpty = allowedGo.length === 0
  const noGoEmpty = allowedNoGo.length === 0
  if (goEmpty && noGoEmpty) {
    throw new Error('pickNextCue: empty allowedCueIds filter')
  }
  const wantGo = goEmpty ? false : noGoEmpty ? true : rng() < config.goCueProbability
  const pool = wantGo ? allowedGo : allowedNoGo
  return pool[Math.floor(rng() * pool.length)]
}

export function pickDistance(rng: RNG): Distance {
  return DISTANCES[Math.floor(rng() * DISTANCES.length)]
}

export function resolveCueAtDistance(
  cue: CueDef,
  distance: Distance | null,
): CueDistanceEntry {
  if (distance !== null && cue.byDistance) {
    return cue.byDistance[distance]
  }
  return { isGo: cue.isGo, expectedResponse: cue.expectedResponse }
}

export interface ClassifyInput {
  isGo: boolean
  cueShownAt: number
  pressedAt: number | null
  responseWindowMs: number
  hesitationThresholdMs: number
  lateThresholdMs: number
  scoreWeights: Record<RepResult, number>
}

export interface ClassifyOutput {
  result: RepResult
  reactionMs: number | null
  score: number
}

export function classifyRep(input: ClassifyInput): ClassifyOutput {
  const {
    isGo,
    cueShownAt,
    pressedAt,
    responseWindowMs,
    hesitationThresholdMs,
    lateThresholdMs,
    scoreWeights,
  } = input

  if (pressedAt !== null && pressedAt < cueShownAt) {
    return wrap('false_start', null, scoreWeights)
  }

  const pressedInWindow =
    pressedAt !== null && pressedAt - cueShownAt <= responseWindowMs

  if (!pressedInWindow) {
    return wrap(isGo ? 'late' : 'correct_no_go', null, scoreWeights)
  }

  const dt = Math.round((pressedAt as number) - cueShownAt)
  if (!isGo) {
    return wrap('false_start', dt, scoreWeights)
  }

  let result: RepResult
  if (dt < hesitationThresholdMs) result = 'correct_go'
  else if (dt < lateThresholdMs) result = 'hesitation'
  else result = 'late'
  return wrap(result, dt, scoreWeights)
}

export function classifyPreCuePress(
  scoreWeights: Record<RepResult, number>,
): ClassifyOutput {
  return wrap('false_start', null, scoreWeights)
}

function wrap(
  result: RepResult,
  reactionMs: number | null,
  scoreWeights: Record<RepResult, number>,
): ClassifyOutput {
  return { result, reactionMs, score: scoreWeights[result] }
}

export interface ValidationError {
  field: keyof DrillConfig
  message: string
}

export function validateDrillConfig(config: DrillConfig): ValidationError[] {
  const errors: ValidationError[] = []
  if (config.preCueMinMs < PRE_CUE_MIN_FLOOR_MS) {
    errors.push({
      field: 'preCueMinMs',
      message: `must be ≥ ${PRE_CUE_MIN_FLOOR_MS}ms`,
    })
  }
  if (config.preCueMaxMs > PRE_CUE_MAX_CEILING_MS) {
    errors.push({
      field: 'preCueMaxMs',
      message: `must be ≤ ${PRE_CUE_MAX_CEILING_MS}ms`,
    })
  }
  if (config.preCueMinMs > config.preCueMaxMs) {
    errors.push({
      field: 'preCueMaxMs',
      message: 'must be ≥ min',
    })
  }
  if (config.rounds < 1) {
    errors.push({ field: 'rounds', message: 'must be ≥ 1' })
  }
  if (config.workMs < 1_000) {
    errors.push({ field: 'workMs', message: 'must be ≥ 1s' })
  }
  if (config.restMs < 0) {
    errors.push({ field: 'restMs', message: 'must be ≥ 0' })
  }
  if (config.perFalseStartPenalty < 0) {
    errors.push({ field: 'perFalseStartPenalty', message: 'must be ≥ 0' })
  }
  if (config.perHesitationPenalty < 0) {
    errors.push({ field: 'perHesitationPenalty', message: 'must be ≥ 0' })
  }
  if (config.hesitationThresholdMs > config.lateThresholdMs) {
    errors.push({
      field: 'lateThresholdMs',
      message: 'must be ≥ hesitation threshold',
    })
  }
  if (config.lateThresholdMs > config.responseWindowMs) {
    errors.push({
      field: 'responseWindowMs',
      message: 'must be ≥ late threshold',
    })
  }
  if (config.allowedCueIds && config.allowedCueIds.length === 0) {
    errors.push({
      field: 'allowedCueIds',
      message: 'must include at least one cue (or null for all)',
    })
  }
  if (config.allowedCueIds && !config.distanceAxisEnabled) {
    const allowed = new Set(config.allowedCueIds)
    const hasGo = GO_CUES.some((c) => allowed.has(c.id))
    if (!hasGo) {
      errors.push({
        field: 'allowedCueIds',
        message:
          'must include at least one go cue when distance axis is disabled',
      })
    }
  }
  return errors
}

export function pendingPenalties(
  reps: RepRecord[],
  perFalseStart: number,
  perHesitation: number,
  cleared: number,
): number {
  const earned = reps.reduce((sum, r) => {
    if (r.result === 'false_start') return sum + perFalseStart
    if (r.result === 'hesitation') return sum + perHesitation
    return sum
  }, 0)
  return Math.max(0, earned - cleared)
}

export interface CueBreakdownRow {
  cueId: CueDef['id']
  reps: number
  correct: number
  falseStarts: number
  hesitations: number
  lateMisses: number
  avgRtMs: number | null
  best10AvgRtMs: number | null
}

/**
 * Mean of the (up to) 10 fastest values. Returns null if the input is empty.
 * Phase 5 — single source of truth for the best-10 metric, used by
 * cueBreakdown, sessionTrend (per-session best-10), and cueAggregate
 * (cross-session best-10).
 */
export function best10AvgOf(times: number[]): number | null {
  if (times.length === 0) return null
  const sorted = [...times].sort((a, b) => a - b).slice(0, 10)
  return Math.round(sorted.reduce((a, b) => a + b, 0) / sorted.length)
}

function correctGoTimesOf(reps: RepRecord[]): number[] {
  return reps
    .filter((r) => r.result === 'correct_go' && r.reactionMs !== null)
    .map((r) => r.reactionMs as number)
}

export function cueBreakdown(reps: RepRecord[]): CueBreakdownRow[] {
  const byId = new Map<CueDef['id'], RepRecord[]>()
  for (const r of reps) {
    const list = byId.get(r.cueId) ?? []
    list.push(r)
    byId.set(r.cueId, list)
  }
  return Array.from(byId.entries()).map(([cueId, list]) => {
    const correctGoTimes = correctGoTimesOf(list)
    const avgRtMs =
      correctGoTimes.length === 0
        ? null
        : Math.round(
            correctGoTimes.reduce((a, b) => a + b, 0) / correctGoTimes.length,
          )
    return {
      cueId,
      reps: list.length,
      correct: list.filter(
        (r) => r.result === 'correct_go' || r.result === 'correct_no_go',
      ).length,
      falseStarts: list.filter((r) => r.result === 'false_start').length,
      hesitations: list.filter((r) => r.result === 'hesitation').length,
      lateMisses: list.filter((r) => r.result === 'late').length,
      avgRtMs,
      best10AvgRtMs: best10AvgOf(correctGoTimes),
    }
  })
}

export type PriorGoStreakBucket = '0' | '1' | '2' | '3+'

export interface AntiRhythmStats {
  overallFalseStartRate: number
  buckets: Record<PriorGoStreakBucket, { falseStarts: number; total: number }>
  narrative: string
}

function priorGoStreakBucketOf(n: number): PriorGoStreakBucket {
  if (n <= 0) return '0'
  if (n === 1) return '1'
  if (n === 2) return '2'
  return '3+'
}

export function antiRhythmSignal(reps: RepRecord[]): AntiRhythmStats {
  const buckets: AntiRhythmStats['buckets'] = {
    '0': { falseStarts: 0, total: 0 },
    '1': { falseStarts: 0, total: 0 },
    '2': { falseStarts: 0, total: 0 },
    '3+': { falseStarts: 0, total: 0 },
  }
  let streak = 0
  let totalGoReps = 0
  let totalFalseStarts = 0
  for (const r of reps) {
    if (r.isGo) {
      const b = priorGoStreakBucketOf(streak)
      buckets[b].total += 1
      if (r.result === 'false_start') buckets[b].falseStarts += 1
      totalGoReps += 1
      if (r.result === 'false_start') totalFalseStarts += 1
      streak += 1
    } else {
      streak = 0
    }
  }
  const overallFalseStartRate =
    totalGoReps === 0 ? 0 : totalFalseStarts / totalGoReps

  let narrative = 'No rhythm pattern detected.'
  let bestBucket: PriorGoStreakBucket | null = null
  let bestRate = -1
  for (const key of Object.keys(buckets) as PriorGoStreakBucket[]) {
    const b = buckets[key]
    if (b.total < 3) continue
    const rate = b.falseStarts / b.total
    if (
      rate > bestRate &&
      overallFalseStartRate > 0 &&
      rate >= overallFalseStartRate * 1.5
    ) {
      bestRate = rate
      bestBucket = key
    }
  }
  if (bestBucket !== null) {
    const pct = Math.round(bestRate * 100)
    const label =
      bestBucket === '0'
        ? 'a non-go cue'
        : bestBucket === '3+'
          ? '3+ consecutive go cues'
          : `${bestBucket} consecutive go cue${bestBucket === '1' ? '' : 's'}`
    narrative = `False starts most often after ${label} (${pct}%).`
  }

  return { overallFalseStartRate, buckets, narrative }
}

export function summarize(reps: RepRecord[]): SessionSummary {
  const reactionTimes = reps
    .filter((r) => r.result === 'correct_go' && r.reactionMs !== null)
    .map((r) => r.reactionMs as number)

  const avgReactionMs =
    reactionTimes.length === 0
      ? null
      : Math.round(
          reactionTimes.reduce((a, b) => a + b, 0) / reactionTimes.length,
        )

  return {
    reps: reps.length,
    correct: reps.filter(
      (r) => r.result === 'correct_go' || r.result === 'correct_no_go',
    ).length,
    falseStarts: reps.filter((r) => r.result === 'false_start').length,
    lateMisses: reps.filter((r) => r.result === 'late').length,
    hesitations: reps.filter((r) => r.result === 'hesitation').length,
    score: reps.reduce((a, r) => a + r.score, 0),
    avgReactionMs,
  }
}

import { CUE_LIBRARY } from '../cues/library'
import type {
  CueId,
  DrillConfig,
  RepRecord,
  RepResult,
  SessionRecord,
} from './types'
import { DEFAULT_DRILL_CONFIG } from './types'
import { best10AvgOf } from './drill'

const CUE_IS_GO: Record<CueId, boolean> = (() => {
  const m = {} as Record<CueId, boolean>
  for (const c of CUE_LIBRARY) m[c.id] = c.isGo
  return m
})()

export interface SessionTrendPoint {
  sessionId: string
  startedAt: number
  reps: number
  falseStartRate: number
  hesitationRate: number
  lateRate: number
  avgRtMs: number | null
  best10AvgRtMs: number | null
  score: number
}

export interface CueTrendPoint {
  sessionId: string
  startedAt: number
  cueId: CueId
  reps: number
  avgRtMs: number | null
  errorRate: number
}

export interface CueAggregateRow {
  cueId: CueId
  isGo: boolean
  reps: number
  sessions: number
  avgRtMs: number | null
  best10AvgRtMs: number | null
  errorRate: number
  goWeakness: number | null
  noGoWeakness: number | null
}

export type CueCompareClassification =
  | 'both_measured'
  | 'both_error_only'
  | 'candidate_only'
  | 'baseline_only'

export interface CueCompareRow {
  cueId: CueId
  classification: CueCompareClassification
  deltaAvgRtMs: number | null
  deltaErrorRate: number
}

export interface SessionDelta {
  baselineId: string
  candidateId: string
  deltaAvgRtMs: number | null
  deltaScore: number | null
  deltaFalseStartRate: number
  deltaHesitationRate: number
  weightsDiffer: boolean
  perCue: CueCompareRow[]
}

export interface TaperRecommendation {
  cueIds: CueId[]
  reason: string
}

export interface TaperProfileBlueprint {
  config: DrillConfig
  reason: string
}

/**
 * Phase 5 — assemble a taper-mode DrillConfig from recent history. Pure;
 * the SettingsScreen handler does the persistence. Returns `null` if there
 * isn't enough data to pick at least one cue.
 *
 * Taper rule (decision-memo D6):
 *   rounds: 3 · workMs: 60s · restMs: 30s · maxReps: null
 *   allowedCueIds: pickTaperCues(cueAggregate(sessions, reps), k)
 *
 * `baseConfig` is the user's currently active profile config — we copy it so
 * the taper profile inherits their preferred thresholds / scoring weights.
 */
export function buildTaperProfileBlueprint(
  sessions: readonly SessionRecord[],
  repsBySession: Map<string, RepRecord[]>,
  baseConfig: DrillConfig = DEFAULT_DRILL_CONFIG,
  k = 3,
): TaperProfileBlueprint | null {
  const agg = cueAggregate(sessions, repsBySession)
  const rec = pickTaperCues(agg, k)
  if (rec.cueIds.length === 0) return null
  return {
    config: {
      ...baseConfig,
      rounds: 3,
      workMs: 60_000,
      restMs: 30_000,
      maxReps: null,
      allowedCueIds: rec.cueIds,
    },
    reason: rec.reason,
  }
}

// ---------------------------------------------------------------------------
// Per-session aggregators (small private helpers reused across exports)

function correctGoTimes(reps: RepRecord[]): number[] {
  return reps
    .filter((r) => r.result === 'correct_go' && r.reactionMs !== null)
    .map((r) => r.reactionMs as number)
}

function trendPointFromReps(
  sessionId: string,
  startedAt: number,
  reps: RepRecord[],
): SessionTrendPoint {
  const total = reps.length
  const goTimes = correctGoTimes(reps)
  const avg =
    goTimes.length === 0
      ? null
      : Math.round(goTimes.reduce((a, b) => a + b, 0) / goTimes.length)
  return {
    sessionId,
    startedAt,
    reps: total,
    falseStartRate:
      total === 0 ? 0 : reps.filter((r) => r.result === 'false_start').length / total,
    hesitationRate:
      total === 0 ? 0 : reps.filter((r) => r.result === 'hesitation').length / total,
    lateRate:
      total === 0 ? 0 : reps.filter((r) => r.result === 'late').length / total,
    avgRtMs: avg,
    best10AvgRtMs: best10AvgOf(goTimes),
    score: reps.reduce((a, r) => a + r.score, 0),
  }
}

// ---------------------------------------------------------------------------
// Public API

export function sessionTrend(
  sessions: readonly SessionRecord[],
  repsBySession: Map<string, RepRecord[]>,
): SessionTrendPoint[] {
  return sessions
    .filter((s) => (repsBySession.get(s.id) ?? []).length > 0)
    .map((s) =>
      trendPointFromReps(s.id, s.startedAt, repsBySession.get(s.id) ?? []),
    )
    .sort((a, b) => a.startedAt - b.startedAt)
}

export function cueTrend(
  sessions: readonly SessionRecord[],
  repsBySession: Map<string, RepRecord[]>,
): CueTrendPoint[] {
  const out: CueTrendPoint[] = []
  const ordered = [...sessions].sort((a, b) => a.startedAt - b.startedAt)
  for (const s of ordered) {
    const reps = repsBySession.get(s.id) ?? []
    if (reps.length === 0) continue
    const byCue = new Map<CueId, RepRecord[]>()
    for (const r of reps) {
      const list = byCue.get(r.cueId) ?? []
      list.push(r)
      byCue.set(r.cueId, list)
    }
    for (const [cueId, list] of byCue) {
      const goTimes = correctGoTimes(list)
      const avg =
        goTimes.length === 0
          ? null
          : Math.round(goTimes.reduce((a, b) => a + b, 0) / goTimes.length)
      const correct = list.filter(
        (r) => r.result === 'correct_go' || r.result === 'correct_no_go',
      ).length
      out.push({
        sessionId: s.id,
        startedAt: s.startedAt,
        cueId,
        reps: list.length,
        avgRtMs: avg,
        errorRate: list.length === 0 ? 0 : (list.length - correct) / list.length,
      })
    }
  }
  return out
}

export function cueAggregate(
  sessions: readonly SessionRecord[],
  repsBySession: Map<string, RepRecord[]>,
): CueAggregateRow[] {
  const byCue = new Map<CueId, RepRecord[]>()
  const sessionsPerCue = new Map<CueId, Set<string>>()
  for (const s of sessions) {
    const reps = repsBySession.get(s.id) ?? []
    for (const r of reps) {
      const list = byCue.get(r.cueId) ?? []
      list.push(r)
      byCue.set(r.cueId, list)
      const sset = sessionsPerCue.get(r.cueId) ?? new Set<string>()
      sset.add(s.id)
      sessionsPerCue.set(r.cueId, sset)
    }
  }
  const rows: CueAggregateRow[] = []
  for (const [cueId, list] of byCue) {
    const isGo = CUE_IS_GO[cueId] ?? true
    const goTimes = correctGoTimes(list)
    const avg =
      goTimes.length === 0
        ? null
        : Math.round(goTimes.reduce((a, b) => a + b, 0) / goTimes.length)
    const correct = list.filter(
      (r) => r.result === 'correct_go' || r.result === 'correct_no_go',
    ).length
    const errorRate =
      list.length === 0 ? 0 : (list.length - correct) / list.length
    const goWeakness =
      isGo && avg !== null ? avg / 1000 + errorRate : null
    const noGoWeakness = !isGo ? errorRate : null
    rows.push({
      cueId,
      isGo,
      reps: list.length,
      sessions: sessionsPerCue.get(cueId)?.size ?? 0,
      avgRtMs: avg,
      best10AvgRtMs: best10AvgOf(goTimes),
      errorRate,
      goWeakness,
      noGoWeakness,
    })
  }
  return rows
}

// ---------------------------------------------------------------------------
// Taper picker — see decision-memo D5 for the go/no-go split rationale.

const MIN_REPS_PER_CUE = 5
const MIN_SESSIONS_PER_CUE = 2

function eligible(row: CueAggregateRow): boolean {
  return row.reps >= MIN_REPS_PER_CUE && row.sessions >= MIN_SESSIONS_PER_CUE
}

function byWeaknessDesc<K extends 'goWeakness' | 'noGoWeakness'>(
  field: K,
): (a: CueAggregateRow, b: CueAggregateRow) => number {
  return (a, b) => {
    const av = a[field] ?? -Infinity
    const bv = b[field] ?? -Infinity
    if (bv !== av) return bv - av
    return a.cueId < b.cueId ? -1 : a.cueId > b.cueId ? 1 : 0
  }
}

export function pickTaperCues(
  aggregate: readonly CueAggregateRow[],
  k: number,
): TaperRecommendation {
  if (k <= 0) return { cueIds: [], reason: 'k must be ≥ 1' }
  const eligibleRows = aggregate.filter(eligible)
  if (eligibleRows.length === 0) {
    return {
      cueIds: [],
      reason:
        'Not enough data — every cue has fewer than 5 reps across at least 2 sessions. Drill more variety first.',
    }
  }
  const goSlots = Math.max(1, Math.floor(k * 0.7))
  const noGoSlots = k - goSlots
  const goPool = eligibleRows
    .filter((r) => r.isGo && r.goWeakness !== null)
    .sort(byWeaknessDesc('goWeakness'))
  const noGoPool = eligibleRows
    .filter((r) => !r.isGo && r.noGoWeakness !== null)
    .sort(byWeaknessDesc('noGoWeakness'))

  // Take initial slots from each pool, then fill any deficit from the other.
  const goPicks = goPool.slice(0, goSlots)
  const noGoPicks = noGoPool.slice(0, noGoSlots)
  const goShort = goSlots - goPicks.length
  const noGoShort = noGoSlots - noGoPicks.length
  const filledFromNoGo = noGoPool
    .slice(noGoPicks.length, noGoPicks.length + goShort)
  const filledFromGo = goPool.slice(goPicks.length, goPicks.length + noGoShort)
  const all = [...goPicks, ...filledFromNoGo, ...noGoPicks, ...filledFromGo]
  const cueIds = all.map((r) => r.cueId)

  const goNames = goPicks.map((r) => r.cueId).join(', ')
  const noGoNames = noGoPicks.map((r) => r.cueId).join(', ')
  const parts: string[] = []
  if (goNames) parts.push(`slowest go cues: ${goNames}`)
  if (noGoNames) parts.push(`weakest no-go cues: ${noGoNames}`)
  if (filledFromNoGo.length > 0)
    parts.push(`extra no-go: ${filledFromNoGo.map((r) => r.cueId).join(', ')}`)
  if (filledFromGo.length > 0)
    parts.push(`extra go: ${filledFromGo.map((r) => r.cueId).join(', ')}`)
  const reason =
    cueIds.length === 0
      ? 'Not enough eligible cues. Drill more variety first.'
      : parts.join(' · ')
  return { cueIds, reason }
}

// ---------------------------------------------------------------------------
// Session comparison

function scoreByResultOf(reps: RepRecord[]): Map<RepResult, number> {
  const m = new Map<RepResult, number>()
  for (const r of reps) {
    if (!m.has(r.result)) m.set(r.result, r.score)
  }
  return m
}

function weightsDifferBetween(
  a: Map<RepResult, number>,
  b: Map<RepResult, number>,
): boolean {
  for (const [k, va] of a) {
    const vb = b.get(k)
    if (vb !== undefined && vb !== va) return true
  }
  return false
}

function cuePerf(
  reps: RepRecord[],
  cueId: CueId,
): { count: number; correct: number; avgRtMs: number | null; errorRate: number } {
  const list = reps.filter((r) => r.cueId === cueId)
  if (list.length === 0) {
    return { count: 0, correct: 0, avgRtMs: null, errorRate: 0 }
  }
  const correct = list.filter(
    (r) => r.result === 'correct_go' || r.result === 'correct_no_go',
  ).length
  const goTimes = correctGoTimes(list)
  const avg =
    goTimes.length === 0
      ? null
      : Math.round(goTimes.reduce((a, b) => a + b, 0) / goTimes.length)
  return {
    count: list.length,
    correct,
    avgRtMs: avg,
    errorRate: (list.length - correct) / list.length,
  }
}

export function compareSessions(
  baseline: SessionRecord,
  candidate: SessionRecord,
  baselineReps: RepRecord[],
  candidateReps: RepRecord[],
): SessionDelta {
  const baseTrend = trendPointFromReps(
    baseline.id,
    baseline.startedAt,
    baselineReps,
  )
  const candTrend = trendPointFromReps(
    candidate.id,
    candidate.startedAt,
    candidateReps,
  )
  const weightsDiffer = weightsDifferBetween(
    scoreByResultOf(baselineReps),
    scoreByResultOf(candidateReps),
  )
  const cueIds = new Set<CueId>()
  for (const r of baselineReps) cueIds.add(r.cueId)
  for (const r of candidateReps) cueIds.add(r.cueId)
  const perCue: CueCompareRow[] = []
  for (const cueId of cueIds) {
    const a = cuePerf(baselineReps, cueId)
    const b = cuePerf(candidateReps, cueId)
    if (a.count === 0 && b.count > 0) {
      perCue.push({
        cueId,
        classification: 'candidate_only',
        deltaAvgRtMs: null,
        deltaErrorRate: 0,
      })
      continue
    }
    if (b.count === 0 && a.count > 0) {
      perCue.push({
        cueId,
        classification: 'baseline_only',
        deltaAvgRtMs: null,
        deltaErrorRate: 0,
      })
      continue
    }
    if (a.avgRtMs === null || b.avgRtMs === null) {
      // Both sides have reps but at least one has zero correct_go RTs.
      perCue.push({
        cueId,
        classification: 'both_error_only',
        deltaAvgRtMs: null,
        deltaErrorRate: b.errorRate - a.errorRate,
      })
      continue
    }
    perCue.push({
      cueId,
      classification: 'both_measured',
      deltaAvgRtMs: b.avgRtMs - a.avgRtMs,
      deltaErrorRate: b.errorRate - a.errorRate,
    })
  }
  perCue.sort((x, y) => (x.cueId < y.cueId ? -1 : x.cueId > y.cueId ? 1 : 0))

  const deltaAvgRtMs =
    baseTrend.avgRtMs === null || candTrend.avgRtMs === null
      ? null
      : candTrend.avgRtMs - baseTrend.avgRtMs

  return {
    baselineId: baseline.id,
    candidateId: candidate.id,
    deltaAvgRtMs,
    deltaScore: weightsDiffer ? null : candTrend.score - baseTrend.score,
    deltaFalseStartRate: candTrend.falseStartRate - baseTrend.falseStartRate,
    deltaHesitationRate: candTrend.hesitationRate - baseTrend.hesitationRate,
    weightsDiffer,
    perCue,
  }
}

